);

-- R. BÄ°LDÄ°RÄ°MLER
CREATE TABLE IF NOT EXISTS public.bildirimler (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gonderen_id UUID REFERENCES public.profiller(id) ON DELETE SET NULL,
    alici_id UUID REFERENCES public.profiller(id) ON DELETE CASCADE,
    mesaj TEXT NOT NULL,
    tip VARCHAR(255) NOT NULL,
    ilgili_kayit_id BIGINT,
    okundu BOOLEAN DEFAULT FALSE,
    olusturulma_tarihi TIMESTAMPTZ DEFAULT NOW()
);

-- S. SÄ°STEM Ä°ÅLEM LOGLARI
CREATE TABLE IF NOT EXISTS public.system_islem_loglari (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.profiller(id) ON DELETE SET NULL,
    islem_tipi TEXT NOT NULL,
    tablo_adi TEXT NOT NULL,
    kayit_id TEXT,
    eski_veri JSONB,
    yeni_veri JSONB,
    tarih TIMESTAMPTZ DEFAULT NOW()
);

-- 3. YETKÄ°LENDÄ°RÄ°LMÄ°Å RPC FONKSÄ°YONLARI (NEXT.JS KULLANIMI Ä°Ã‡Ä°N)

-- Rol Kontrol YardÄ±mcÄ± Fonksiyonu
CREATE OR REPLACE FUNCTION public.get_user_role(user_id UUID)
RETURNS TEXT AS $$
DECLARE
  u_role TEXT;
BEGIN
  SELECT rol INTO u_role FROM public.profiller WHERE id = user_id;
  RETURN COALESCE(u_role, 'Beklemede');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_v3_assign_all_olcutler(
  p_user_id UUID,
  p_donem_id UUID,
  p_olcut_ids INT[]
)
RETURNS VOID AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiller WHERE id = auth.uid() AND (rol ILIKE '%admin%' OR rol ILIKE '%yÃ¶netici%' OR rol ILIKE '%yonetici%')) THEN
    RAISE EXCEPTION 'Unauthorized: Atama yapma yetkiniz yok.';
  END IF;

  DELETE FROM public.kullanici_olcut_atamalari WHERE user_id = p_user_id AND donem_id = p_donem_id;

  IF p_olcut_ids IS NOT NULL AND array_length(p_olcut_ids, 1) > 0 THEN
    INSERT INTO public.kullanici_olcut_atamalari (user_id, donem_id, alt_olcut_id)
    SELECT p_user_id, p_donem_id, unnest(p_olcut_ids);
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_v3_sync_birim_atamalari(
  p_user_id UUID,
  p_donem_id UUID,
  p_scope_olcut_ids INT[],
  p_selected_olcut_ids INT[]
)
RETURNS VOID AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiller WHERE id = auth.uid() AND (rol ILIKE '%admin%' OR rol ILIKE '%yÃ¶netici%' OR rol ILIKE '%yonetici%')) THEN
    RAISE EXCEPTION 'Unauthorized: Atama yetkiniz yok.';
  END IF;

  DELETE FROM public.kullanici_olcut_atamalari WHERE user_id = p_user_id AND donem_id = p_donem_id AND alt_olcut_id = ANY(p_scope_olcut_ids);
  DELETE FROM public.kullanici_olcut_atamalari WHERE donem_id = p_donem_id AND alt_olcut_id = ANY(p_selected_olcut_ids) AND user_id != p_user_id;

  IF p_selected_olcut_ids IS NOT NULL AND array_length(p_selected_olcut_ids, 1) > 0 THEN
    INSERT INTO public.kullanici_olcut_atamalari (user_id, donem_id, alt_olcut_id)
    SELECT p_user_id, p_donem_id, unnest(p_selected_olcut_ids);
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- KOORDÄ°NATÃ–R ATAMA V4
CREATE OR REPLACE FUNCTION public.rpc_v4_assign_koordinator_with_role(
  p_user_id UUID,
  p_baslik TEXT,
  p_rol TEXT
)
RETURNS VOID AS $$
DECLARE
  current_role TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiller WHERE id = auth.uid() AND (rol ILIKE '%admin%' OR rol ILIKE '%yÃ¶netici%' OR rol ILIKE '%yonetici%')) THEN
    RAISE EXCEPTION 'Unauthorized: Atama yapma yetkiniz yok.';
  END IF;

  SELECT rol INTO current_role FROM public.profiller WHERE id = p_user_id;

  IF current_role ILIKE '%admin%' OR current_role ILIKE '%yÃ¶netici%' OR current_role ILIKE '%yonetici%' THEN
    -- YÃ¶neticinin rolÃ¼ deÄŸiÅŸtirilemez
  ELSE
    IF p_rol = 'GÃ¶zlemci' OR p_rol = 'Gozlemci' THEN
      UPDATE public.profiller SET rol = 'Gozlemci' WHERE id = p_user_id;
    ELSE
      UPDATE public.profiller SET rol = 'BirimSorumlusu' WHERE id = p_user_id;
    END IF;
  END IF;

  DELETE FROM public.baslik_koordinatorleri WHERE kullanici_id = p_user_id AND baslik = p_baslik;
  INSERT INTO public.baslik_koordinatorleri (kullanici_id, baslik) VALUES (p_user_id, p_baslik);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- KOORDÄ°NATÃ–R SÄ°LME V4
CREATE OR REPLACE FUNCTION public.rpc_v4_remove_koordinator(
  p_user_id UUID,
  p_baslik TEXT
)
RETURNS VOID AS $$
DECLARE
  current_role TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiller WHERE id = auth.uid() AND (rol ILIKE '%admin%' OR rol ILIKE '%yÃ¶netici%' OR rol ILIKE '%yonetici%')) THEN
    RAISE EXCEPTION 'Unauthorized: Atama silme yetkiniz yok.';
  END IF;

  DELETE FROM public.baslik_koordinatorleri WHERE kullanici_id = p_user_id AND baslik = p_baslik;

  IF NOT EXISTS (SELECT 1 FROM public.baslik_koordinatorleri WHERE kullanici_id = p_user_id) THEN
    SELECT rol INTO current_role FROM public.profiller WHERE id = p_user_id;
    IF current_role = 'Gozlemci' THEN
      UPDATE public.profiller SET rol = 'BirimSorumlusu' WHERE id = p_user_id;
    END IF;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Yeni KullanÄ±cÄ± KaydolduÄŸunda Profil OluÅŸturma Trigger'Ä±
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiller (id, email, ad_soyad, rol)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'ad_soyad', NEW.raw_user_meta_data->>'full_name', SPLIT_PART(NEW.email, '@', 1)),
    'Beklemede'
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

