-- YENÄ° POLÄ°TÄ°KALARI KUR (TEXT DÃ–NÃœÅÃœMÃœ VE KESÄ°N UYUMLU)
CREATE POLICY "profiller_read_all" ON public.profiller FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "profiller_update_own" ON public.profiller FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "profiller_admin_all" ON public.profiller FOR ALL USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "donemler_read_all" ON public.donemler FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "donemler_admin_all" ON public.donemler FOR ALL USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "birimler_read_all" ON public.birimler FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "birimler_admin_all" ON public.birimler FOR ALL USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "system_islem_loglari_read" ON public.system_islem_loglari FOR SELECT USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']) OR EXISTS (SELECT 1 FROM public.baslik_koordinatorleri WHERE kullanici_id = auth.uid()));
CREATE POLICY "system_islem_loglari_insert" ON public.system_islem_loglari FOR INSERT WITH CHECK (auth.role() = 'authenticated');

CREATE POLICY "duyurular_read_all" ON public.duyurular FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "duyurular_admin_all" ON public.duyurular FOR ALL USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "duyuru_okumalar_all" ON public.duyuru_okumalar FOR ALL USING (auth.role() = 'authenticated');

CREATE POLICY "anketler_read_all" ON public.anketler FOR SELECT USING (true);
CREATE POLICY "anketler_manage_assigned" ON public.anketler FOR ALL USING (EXISTS (SELECT 1 FROM public.kullanici_olcut_atamalari ka WHERE ka.alt_olcut_id::text = public.anketler.alt_olcut_id AND ka.user_id = auth.uid()) OR public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "anket_cevaplari_insert" ON public.anket_cevaplari FOR INSERT WITH CHECK (true);
CREATE POLICY "anket_cevaplari_read_assigned" ON public.anket_cevaplari FOR SELECT USING (EXISTS (SELECT 1 FROM public.anketler a LEFT JOIN public.kullanici_olcut_atamalari ka ON ka.alt_olcut_id::text = a.alt_olcut_id WHERE a.id = public.anket_cevaplari.anket_id AND (ka.user_id = auth.uid() OR public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']))));

CREATE POLICY "ana_basliklar_read" ON public.ana_basliklar FOR SELECT USING (true);
CREATE POLICY "alt_olcutler_read" ON public.alt_olcutler FOR SELECT USING (true);
CREATE POLICY "ana_basliklar_admin" ON public.ana_basliklar FOR ALL USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));
