CREATE POLICY "puko_degerlendirmeleri_read_secure" ON public.puko_degerlendirmeleri FOR SELECT TO authenticated USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%', '%gÃ¶zlemci%', '%gozlemci%']) OR EXISTS (SELECT 1 FROM public.baslik_koordinatorleri bk JOIN public.alt_olcutler ao ON ao.id = public.puko_degerlendirmeleri.alt_olcut_id JOIN public.ana_basliklar ab ON ab.id = ao.ana_baslik_id WHERE bk.kullanici_id = auth.uid() AND ((bk.baslik = 'Kalite GÃ¼vencesi' AND ab.baslik_adi = 'KALÄ°TE GÃœVENCESÄ° SÄ°STEMÄ°') OR (bk.baslik = 'EÄŸitim-Ã–ÄŸretim' AND ab.baslik_adi = 'EÄÄ°TÄ°M VE Ã–ÄRETÄ°M') OR (bk.baslik = 'AraÅŸtÄ±rma ve GeliÅŸtirme' AND ab.baslik_adi = 'ARAÅTIRMA VE GELÄ°ÅTÄ°RME') OR (bk.baslik = 'Toplumsal KatkÄ±' AND ab.baslik_adi = 'TOPLUMSAL KATKI') OR (bk.baslik = 'YÃ¶netim Sistemi' AND ab.baslik_adi = 'YÃ–NETÄ°M SÄ°STEMÄ°'))) OR EXISTS (SELECT 1 FROM public.kullanici_olcut_atamalari ka WHERE ka.alt_olcut_id = public.puko_degerlendirmeleri.alt_olcut_id AND ka.user_id = auth.uid()));
CREATE POLICY "Users can manage assigned evaluations" ON public.puko_degerlendirmeleri FOR ALL USING (EXISTS (SELECT 1 FROM public.kullanici_olcut_atamalari ka WHERE ka.alt_olcut_id = public.puko_degerlendirmeleri.alt_olcut_id AND ka.user_id = auth.uid()) OR public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

CREATE POLICY "ozdegerlendirme_raporlari_read_secure" ON public.ozdegerlendirme_raporlari FOR SELECT TO authenticated USING (public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%', '%gÃ¶zlemci%', '%gozlemci%']) OR EXISTS (SELECT 1 FROM public.baslik_koordinatorleri bk JOIN public.alt_olcutler ao ON ao.id::text = public.ozdegerlendirme_raporlari.alt_olcut_id JOIN public.ana_basliklar ab ON ab.id = ao.ana_baslik_id WHERE bk.kullanici_id = auth.uid() AND ((bk.baslik = 'Kalite GÃ¼vencesi' AND ab.baslik_adi = 'KALÄ°TE GÃœVENCESÄ° SÄ°STEMÄ°') OR (bk.baslik = 'EÄŸitim-Ã–ÄŸretim' AND ab.baslik_adi = 'EÄÄ°TÄ°M VE Ã–ÄRETÄ°M') OR (bk.baslik = 'AraÅŸtÄ±rma ve GeliÅŸtirme' AND ab.baslik_adi = 'ARAÅTIRMA VE GELÄ°ÅTÄ°RME') OR (bk.baslik = 'Toplumsal KatkÄ±' AND ab.baslik_adi = 'TOPLUMSAL KATKI') OR (bk.baslik = 'YÃ¶netim Sistemi' AND ab.baslik_adi = 'YÃ–NETÄ°M SÄ°STEMÄ°'))) OR EXISTS (SELECT 1 FROM public.kullanici_olcut_atamalari ka WHERE ka.alt_olcut_id::text = public.ozdegerlendirme_raporlari.alt_olcut_id AND ka.user_id = auth.uid()));
CREATE POLICY "Users can manage assigned reports" ON public.ozdegerlendirme_raporlari FOR ALL USING (EXISTS (SELECT 1 FROM public.kullanici_olcut_atamalari ka WHERE ka.alt_olcut_id::text = public.ozdegerlendirme_raporlari.alt_olcut_id AND ka.user_id = auth.uid()) OR public.get_user_role(auth.uid()) ILIKE ANY (ARRAY['%admin%', '%yÃ¶netici%', '%yonetici%']));

