CREATE POLICY "dokumanlar_update" ON storage.objects FOR UPDATE USING (bucket_id = 'dokumanlar');
CREATE POLICY "dokumanlar_delete" ON storage.objects FOR DELETE USING (bucket_id = 'dokumanlar');

