CREATE POLICY "kanit_dosyalari_update" ON storage.objects FOR UPDATE USING (bucket_id = 'kanit_dosyalari');
CREATE POLICY "kanit_dosyalari_delete" ON storage.objects FOR DELETE USING (bucket_id = 'kanit_dosyalari');

