INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (6, 'A.1.1', 'Misyon, Vizyon, Stratejik AmaÃ§lar ve Hedefler', 'Mission, Vision, Strategic Goals and Objectives', 'Ø§Ù„Ø±Ø³Ø§Ù„Ø© ÙˆØ§Ù„Ø±Ø¤ÙŠØ© ÙˆØ§Ù„Ø£Ù‡Ø¯Ø§Ù ÙˆØ§Ù„ØºØ§ÙŠØ§Øª Ø§Ù„Ø§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ©', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda stratejik plan kapsamÄ±nda tanÄ±mlanmÄ±ÅŸ misyon, vizyon, stratejik amaÃ§lar bulunmamaktadÄ±r.","2":"Kurumun stratejik plan kapsamÄ±nda tanÄ±mlanmÄ±ÅŸ misyon, vizyon, stratejik amaÃ§ ve hedefleri bulunmaktadÄ±r. Ancak bunlarÄ± gerÃ§ekleÅŸtirmek amacÄ±yla yapÄ±lan uygulamalar bulunmamaktadÄ±r veya mevcut uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Stratejik plan kapsamÄ±nda stratejik amaÃ§larÄ± ve hedefleri doÄŸrultusunda kurumun tamamÄ±nda yapÄ±lan uygulamalar bulunmaktadÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak stratejik planÄ±n izlenmesi iÃ§in gerekli mekanizmalar oluÅŸturulmamÄ±ÅŸtÄ±r ve/veya stratejik plan ve/veya herhangi bir karar alma sÃ¼recinde kullanÄ±lmamaktadÄ±r.","4":"Stratejik plan kapsamÄ±nda stratejik amaÃ§lar ve hedefler doÄŸrultusundaki tÃ¼m alanlarÄ± kapsayan uygulamalar sistematik olarak ve kurumun iÃ§ kalite gÃ¼vencesi sistemi ile uyumlu olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Stratejik plan kapsamÄ±nda stratejik amaÃ§ ve hedefleri gerÃ§ekleÅŸtirmek Ã¼zere yapÄ±lan olgunlaÅŸmÄ±ÅŸ, sÃ¼rdÃ¼rÃ¼lebilir uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun bu hususta kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no mission, vision or strategic objectives defined within the scope of the strategic plan in the institution.","2":"The institution has a mission, vision, strategic goals and objectives defined within the scope of the strategic plan. However, there are no applications to achieve these or existing applications do not cover all areas.","3":"Within the scope of the strategic plan, there are practices carried out throughout the institution in line with its strategic goals and objectives, and some results have been obtained from these practices. However, the necessary mechanisms for monitoring the strategic plan have not been established and/or are not used in the strategic plan and/or any decision-making process.","4":"Within the scope of the strategic plan, practices covering all areas in line with strategic goals and objectives are monitored systematically and in accordance with the institution''s internal quality assurance system, and measures are taken by evaluating them together with stakeholders.","5":"Mature, sustainable practices implemented to achieve strategic goals and objectives within the scope of the strategic plan have been adopted throughout the institution; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø±Ø³Ø§Ù„Ø© Ø£Ùˆ Ø±Ø¤ÙŠØ© Ø£Ùˆ Ø£Ù‡Ø¯Ø§Ù Ø§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© Ù…Ø­Ø¯Ø¯Ø© Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ø§Ù„Ø®Ø·Ø© Ø§Ù„Ø§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù„Ù„Ù…Ø¤Ø³Ø³Ø© Ø±Ø³Ø§Ù„Ø© ÙˆØ±Ø¤ÙŠØ© ÙˆØ£Ù‡Ø¯Ø§Ù Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙˆØºØ§ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ø§Ù„Ø®Ø·Ø© Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ù„ØªØ­Ù‚ÙŠÙ‚ Ù‡Ø°Ù‡ Ø§Ù„Ø£Ù‡Ø¯Ø§Ù Ø£Ùˆ Ø£Ù† Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø§Ù„Ù…ÙˆØ¬ÙˆØ¯Ø© Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ÙŠÙˆØ¬Ø¯ Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ø§Ù„Ø®Ø·Ø© Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙŠØªÙ… ØªÙ†ÙÙŠØ°Ù‡Ø§ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ø§ ÙŠØªÙˆØ§ÙÙ‚ Ù…Ø¹ Ø£Ù‡Ø¯Ø§ÙÙ‡Ø§ ÙˆØºØ§ÙŠØ§ØªÙ‡Ø§ Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ©ØŒ ÙˆÙ‚Ø¯ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù