INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (7, 'A.1.2', 'Kalite GÃ¼vencesi, EÄŸitim Ã–ÄŸretim, AraÅŸtÄ±rma GeliÅŸtirme, Toplumsal KatkÄ± ve YÃ¶netim Sistemi PolitikalarÄ±', 'Quality Assurance, Education and Training, Research and Development, Social Contribution and Management System Policies', 'Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©ØŒ Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ØŒ Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ±ØŒ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙˆØ³ÙŠØ§Ø³Ø§Øª Ù†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø©', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda tanÄ±mlÄ± herhangi bir politika bulunmamaktadÄ±r.","2":"Kurumda kalite gÃ¼vencesi, eÄŸitim-Ã¶ÄŸretim, araÅŸtÄ±rma-geliÅŸtirme, toplumsal katkÄ± ve yÃ¶netim sistemi gibi temel alanlarÄ±n bazÄ±larÄ±nda tanÄ±mlÄ± politikalar bulunmaktadÄ±r. Ancak bu politikalar herhangi bir planlama veya karar alma sÃ¼reÃ§lerinde kullanÄ±lmamaktadÄ±r.","3":"Kalite gÃ¼vencesi, eÄŸitim ve Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme, toplumsal katkÄ± ve yÃ¶netim sistemi alanlarÄ±nÄ±n tÃ¼mÃ¼nde tanÄ±mlÄ± politikalar doÄŸrultusunda yapÄ±lan uygulamalar bulunmaktadÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ±nÄ± izlemek iÃ§in gerekli mekanizmalar bulunmamaktadÄ±r.","4":"Kalite gÃ¼vencesi, eÄŸitim ve Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme, toplumsal katkÄ± ve yÃ¶netim sistemi alanlarÄ±ndaki kurumsal politikalarÄ±n birbirleri ile olan iliÅŸkileri kurulmuÅŸ ve politikalardaki bu bÃ¼tÃ¼ncÃ¼l yapÄ± iÃ§ kalite gÃ¼vence sistemini yÃ¶nlendirmektedir; sonuÃ§lar izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"TÃ¼m baÅŸlÄ±klardaki kurumsal politikalar doÄŸrultusunda olgunlaÅŸmÄ±ÅŸ, sÃ¼rdÃ¼rÃ¼lebilir uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir ve karar almalarda esas alÄ±nmaktadÄ±r; bu uygulamalar iÃ§erisinde kuruma Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulama bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no defined policy in the institution.","2":"The institution has defined policies in some of the basic areas such as quality assurance, education-training, research-development, social contribution and management system. However, these policies are not used in any planning or decision-making processes.","3":"There are practices carried out in line with defined policies in all areas of quality assurance, education and training, research and development, social contribution and management system, and some results have been obtained from these practices. However, there are no necessary mechanisms to monitor the results of these practices.","4":"The interrelationships of corporate policies in the fields of quality assurance, education and training, research and development, social contribution and management system have been established and this holistic structure in policies directs the internal quality assurance system; The results are monitored and evaluated together with stakeholders and precautions are taken.","5":"Mature, sustainable practices in line with corporate policies under all headings have been adopted throughout the institution and are taken as basis in decision-making; Among these applications, there are many institution-specific and innovative applications, and some of the applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø³ÙŠØ§Ø³Ø© Ù…Ø­Ø¯Ø¯Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"ÙˆÙ‚Ø¯ Ø­Ø¯Ø¯Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø³ÙŠØ§Ø³Ø§Øª ÙÙŠ Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª Ø§Ù„Ø£Ø³Ø§Ø³ÙŠØ© Ù…Ø«Ù„ Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© ÙˆØ§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ ÙˆØªØ·ÙˆÙŠØ± Ø§Ù„Ø¨Ø­ÙˆØ« ÙˆØ§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙˆÙ†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø§Ø³ØªØ®Ø¯Ø§Ù… Ù‡Ø°Ù‡ Ø§Ù„Ø³ÙŠØ§Ø³Ø§Øª ÙÙŠ Ø£ÙŠ Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ®Ø·ÙŠØ· Ø£Ùˆ Ø§ØªØ®Ø§