INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (8, 'A.1.3', 'Kurumsal Performans YÃ¶netimi', 'Corporate Performance Management', 'Ø¥Ø¯Ø§Ø±Ø© Ø£Ø¯Ø§Ø¡ Ø§Ù„Ø´Ø±ÙƒØ§Øª', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda performans yÃ¶netimi uygulamasÄ± ve stratejik planla uyumlu olarak tanÄ±mlanmÄ±ÅŸ performans gÃ¶stergeleri bulunmamaktadÄ±r.","2":"Kurumda performansÄ± izlemek Ã¼zere bazÄ± gÃ¶stergeler ve mekanizmalar tanÄ±mlanmÄ±ÅŸtÄ±r. Ancak bu gÃ¶stergeleri izlemek Ã¼zere yapÄ±lan uygulamalar bulunmamaktadÄ±r veya mevcut uygulamalar tÃ¼m alanlarÄ±/sÃ¼reÃ§leri (kalite gÃ¼vencesi sistemi, eÄŸitim ve Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme, toplumsal katkÄ±, yÃ¶netim sistemi) kapsamamaktadÄ±r.","3":"TÃ¼m alanlarla iliÅŸkili olarak performans gÃ¶stergeleri ve anahtar performans gÃ¶stergeleri belirlenmiÅŸtir. Ancak bu gÃ¶stergelerin izlenmesi sistematik olmayan ve tÃ¼m alanlarÄ± kapsamayan ÅŸekilde yapÄ±lmaktadÄ±r.","4":"TÃ¼m alanlarla/sÃ¼reÃ§lerle iliÅŸkili tÃ¼m performans gÃ¶stergeleri sistematik ve kurumun iÃ§ kalite gÃ¼vencesi sistemi ile uyumlu olarak izlenmekte ve elde edilen sonuÃ§lar paydaÅŸlarla birlikte deÄŸerlendirilerek karar almalarda kullanÄ±lmakta ve performans yÃ¶netimine iliÅŸkin Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumsal amaÃ§lar doÄŸrultusunda, olgunlaÅŸmÄ±ÅŸ ve sÃ¼rdÃ¼rÃ¼lebilir kurumsal performans yÃ¶netimi kurumun tamamÄ±nda benimsenmiÅŸtir; kuruma Ã¶zgÃ¼ ve yenilikÃ§i uygulamalar bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no performance indicators defined in line with the performance management practice and strategic plan in the institution.","2":"Some indicators and mechanisms have been defined to monitor performance in the institution. However, there are no practices to monitor these indicators, or existing practices do not cover all areas/processes (quality assurance system, education and training, research and development, social contribution, management system).","3":"Performance indicators and key performance indicators have been determined in relation to all areas. However, monitoring of these indicators is done in a non-systematic way and does not cover all areas.","4":"All performance indicators related to all areas/processes are monitored systematically and in compliance with the institution''s internal quality assurance system, and the results obtained are evaluated together with stakeholders and used in decision-making and performance management measures are taken.","5":"In line with corporate objectives, mature and sustainable corporate performance management has been adopted throughout the institution; There are institution-specific and innovative practices, and some of the practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ø¤Ø´Ø±Ø§Øª Ø£Ø¯Ø§Ø¡ Ù…Ø­Ø¯Ø¯Ø© ØªØªÙˆØ§ÙÙ‚ Ù…Ø¹ Ù…Ù…Ø§Ø±Ø³Ø© Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø£Ø¯Ø§Ø¡ ÙˆØ§Ù„Ø®Ø·Ø© Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"ÙˆØªÙ… ØªØ­Ø¯ÙŠØ¯ Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ø¤Ø´Ø±Ø§Øª ÙˆØ§Ù„Ø¢Ù„ÙŠØ§Øª Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ø£Ø¯Ø§Ø¡ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø±ØµØ¯ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ø¤Ø´Ø±Ø§ØªØŒ Ø£Ùˆ Ø£Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ø­Ø§Ù„ÙŠØ© Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª/Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª (Ù†Ø¸Ø§Ù… Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©ØŒ Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ØŒ Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ±ØŒ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©ØŒ Ù†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø©).","3":"ÙˆÙ‚Ø¯ ØªÙ… ØªØ­Ø¯ÙŠØ¯ Ù…Ø¤Ø´Ø±Ø§Øª Ø§Ù„Ø£Ø¯Ø§Ø¡ ÙˆÙ…Ø¤Ø´Ø±Ø§Øª Ø§Ù„Ø£Ø¯Ø§Ø¡ Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠØ© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª. Ø¥Ù„Ø§ Ø£Ù† Ø±ØµØ¯ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ø¤Ø´Ø±Ø§Øª ÙŠØªÙ… Ø¨Ø´ÙƒÙ„ ØºÙŠØ± Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙ„Ø§ ÙŠØ´Ù…Ù„ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø¬Ù…ÙŠØ¹ Ù…Ø¤Ø´Ø±Ø§Øª Ø§Ù„Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø