INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (9, 'A.2.1', 'Birim Kalite Komisyonu', 'Unit Quality Commission', 'Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø¨Ø§Ù„ÙˆØ­Ø¯Ø©', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda kalite gÃ¼vencesi sÃ¼reÃ§lerini yÃ¼rÃ¼tmek Ã¼zere oluÅŸturulmuÅŸ bir kalite komisyonu bulunmamaktadÄ±r.","2":"Kalite komisyonunun yetki, gÃ¶rev ve soru mluluklarÄ± ile organizasyon yapÄ±sÄ± tanÄ±mlanmÄ±ÅŸtÄ±r. Ancak kalite komisyonu bu yetki, gÃ¶rev ve sorumluluklar kapsamÄ±nda planlama ve/veya karar alma sÃ¼reÃ§lerinde etkin rol almamaktadÄ±r.","3":"Kalite komisyonunu yetki, gÃ¶rev ve sorumluluklarÄ± kapsamÄ±nda Ã§alÄ±ÅŸmalarÄ±nÄ± kapsayÄ±cÄ± ve katÄ±lÄ±mcÄ± bir yaklaÅŸÄ±mla ÅŸeffaf olarak yÃ¼rÃ¼tmektedir. Ancak bu uygulamalar kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda yÃ¼rÃ¼tÃ¼lmemektedir ve uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kalite komisyonu yetki, gÃ¶rev ve sorumluluklarÄ± doÄŸrultusunda sistematik ve kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda Ã§alÄ±ÅŸmalarÄ±nÄ± yÃ¼rÃ¼tmekte; yÃ¼rÃ¼tÃ¼len uygulamalardan elde edilen bulgular izlenmekte ve izlem sonuÃ§larÄ± deÄŸerlendirilerek iyileÅŸtirmeler gerÃ§ekleÅŸtirilmektedir.","5":"Kalite komisyonunun kurumsal amaÃ§lar doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve bÃ¼tÃ¼nleÅŸik uygulamalarÄ± kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun kalite yÃ¶netimi kapsamÄ±nda yenilikÃ§i uygulamalarÄ± bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no quality commission established to carry out quality assurance processes in the institution.","2":"The authority, duties and responsibilities of the quality commission and its organizational structure are defined. However, the quality commission does not take an active role in the planning and/or decision-making processes within the scope of these authorities, duties and responsibilities.","3":"The quality commission carries out its work transparently, with an inclusive and participatory approach, within the scope of its powers, duties and responsibilities. However, these practices are not carried out within the scope of holistic quality management in the institution and the results of the practices are not monitored.","4":"The quality commission carries out its work within the scope of systematic and holistic quality management in the institution, in line with its authority, duties and responsibilities; The findings obtained from the practices carried out are monitored and improvements are made by evaluating the monitoring results.","5":"In line with the corporate objectives of the quality commission, sustainable and integrated practices have been adopted throughout the institution; The institution has innovative practices within the scope of quality management, and some of the practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ù„Ø¬Ù†Ø© Ø¬ÙˆØ¯Ø© ØªÙ… Ø¥Ù†Ø´Ø§Ø¤Ù‡Ø§ Ù„ØªÙ†ÙÙŠØ° Ø¹Ù…Ù„ÙŠØ§Øª Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"ØªÙ… ØªØ­Ø¯ÙŠØ¯ ØµÙ„Ø§Ø­ÙŠØ§Øª ÙˆÙˆØ§Ø¬Ø¨Ø§Øª ÙˆÙ…Ø³Ø¤ÙˆÙ„ÙŠØ§Øª Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© ÙˆÙ‡ÙŠÙƒÙ„Ù‡Ø§ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙ‚ÙˆÙ… Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø¨Ø¯ÙˆØ± Ù†Ø´Ø· ÙÙŠ Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ®Ø·ÙŠØ· Ùˆ/Ø£Ùˆ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø± Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ù‡Ø°Ù‡ Ø§Ù„Ø³Ù„Ø·Ø§Øª ÙˆØ§Ù„ÙˆØ§Ø¬Ø¨Ø§Øª ÙˆØ§Ù„Ù…Ø³Ø¤ÙˆÙ„ÙŠØ§Øª.","3":"ÙˆØªÙ…Ø§Ø±Ø³ Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø¹Ù…Ù„Ù‡Ø§ Ø¨Ø´ÙØ§ÙÙŠØ©ØŒ ÙˆØ¨Ù…Ù†Ù‡Ø¬ Ø´Ø§Ù…Ù„ ÙˆØªØ´Ø§Ø±ÙƒÙŠØŒ ÙÙŠ Ù†Ø·Ø§Ù‚ ØµÙ„Ø§Ø­ÙŠØ§ØªÙ‡Ø§ ÙˆÙˆØ§Ø¬Ø¨Ø§ØªÙ‡Ø§ ÙˆÙ…Ø³Ø¤ÙˆÙ„ÙŠØ§ØªÙ‡Ø§. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… ØªÙ†ÙÙŠØ° Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø§Ù„Ø´Ø§Ù…Ù„Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆÙ„Ø§ ÙŠØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªÙ†ÙØ° Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø¹Ù…Ù„Ù‡Ø§ Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¬ÙˆØ¯Ø© Ø§Ù„Ù…Ù†Ù‡Ø¬ÙŠØ© ÙˆØ§Ù„Ø´Ø§Ù…Ù„Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ ØµÙ„Ø§Ø­ÙŠØ§ØªÙ‡Ø§ ÙˆÙˆØ§Ø¬Ø¨Ø§ØªÙ‡Ø§ ÙˆÙ…Ø³Ø¤ÙˆÙ„ÙŠØ§ØªÙ‡Ø§Ø› ÙˆÙŠØªÙ… Ø±ØµØ¯ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ø§Ù„ØªÙŠ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„ÙŠÙ‡Ø§ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…Ù†ÙØ°Ø© ÙˆÙŠØªÙ… Ø¥Ø¬Ø±Ø§Ø¡ ØªØ­Ø³ÙŠÙ†Ø§Øª Ù…Ù† Ø®Ù„Ø§Ù„ ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ø±ØµØ¯.","5":"ÙˆØªÙ…Ø´ÙŠØ§ Ù…Ø¹ Ø§Ù„Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ù…Ø¤Ø³Ø³ÙŠØ© Ù„Ù„Ø¬Ù†Ø© Ø§Ù„Ø¬ÙˆØ¯Ø©ØŒ ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ…ØªÙƒØ§Ù…Ù„Ø© ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø› ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø¨ØªÙƒØ±Ø© ÙÙŠ Ù†Ø·Ø§Ù‚ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¬ÙˆØ¯Ø©ØŒ ÙˆÙŠØªÙ… Ø£Ø®Ø° Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙƒÙ…Ø«Ø§Ù„ Ù…Ù† Ù‚Ø¨Ù„ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aciklama_metni":"","aciklama_metni_en":"","uygulama_alanlari":"","ilk_planlama_tarihi":"","izleme_mekanizmalari":"","uluslararasi_paydaslar":"","performans_gostergeleri":"","degerlendirme_iyilestirme_tarihi":""}'::jsonb) ON CONFLICT (id) DO UPDATE SET olcut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (10, 'A.2.2', 'Ä°Ã§ Kalite GÃ¼vencesi MekanizmalarÄ±', 'Internal Quality Assurance Mechanisms', 'Ø¢Ù„ÙŠØ§Øª Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© Ø§Ù„Ø¯Ø§Ø®Ù„ÙŠØ©', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun iÃ§ kalite gÃ¼vencesi sistemi ve mekanizmalarÄ± bulunmamaktadÄ±r.","2":"Kurumun iÃ§ kalite gÃ¼vencesi mekanizmalarÄ± bulunmaktadÄ±r ancak bu mekanizmalar bÃ¼tÃ¼n alanlarÄ±/sÃ¼reÃ§leri (eÄŸitim v e Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme, toplumsal katkÄ±, yÃ¶netim sistemi) kapsamamaktadÄ±r.","3":"Kurumun tÃ¼m alanlarÄ± ve sÃ¼reÃ§leri kapsayacak ÅŸekilde iÃ§ kalite gÃ¼vencesi mekanizmalarÄ± (sÃ¼reÃ§ler, PUKÃ– Ã§evrimleri, gÃ¶revler, yetki ve sorumluluklar, kalite araÃ§larÄ±) bulunmakta olup; bu iÃ§ kalite gÃ¼vencesi mekanizmalarÄ±ndan bazÄ± uygulama sonuÃ§larÄ± elde edilmiÅŸtir. Ancak bu mekanizmalar kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda yÃ¼rÃ¼tÃ¼lmemektedir ve uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumda tÃ¼m alanlarÄ± ve sÃ¼reÃ§leri kapsayan iÃ§ kalite gÃ¼vencesi mekanizmalarÄ±, tanÄ±mlÄ± sÃ¼reÃ§ler bÃ¼tÃ¼ncÃ¼l bir kalite yÃ¶netimi anlayÄ±ÅŸÄ± kapsamÄ±nda sistematik olarak yÃ¼rÃ¼tÃ¼lmektedir; yÃ¼rÃ¼tÃ¼len uygulamalardan elde edilen bulgular izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlen dirilerek iyileÅŸtirmeler gerÃ§ekleÅŸtirilmektedir.","5":"TÃ¼m alanlarÄ± ve sÃ¼reÃ§leri kapsayan, kurumsal amaÃ§lar doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve bÃ¼tÃ¼nleÅŸik iÃ§ kalite gÃ¼vencesi uygulamalarÄ± kurumun tamamÄ±nda benimsenmiÅŸtir. Kurumun kalite yÃ¶netimi kapsamÄ±nda yenilikÃ§i uygulamalarÄ± bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have an internal quality assurance system and mechanisms.","2":"The institution has internal quality assurance mechanisms, but these mechanisms do not cover all areas/processes (education and training, research and development, social contribution, management system).","3":"The institution has internal quality assurance mechanisms (processes, PDCA cycles, duties, authorities and responsibilities, quality tools) covering all areas and processes; Some implementation results have been obtained from these internal quality assurance mechanisms. However, these mechanisms are not implemented within the scope of holistic quality management in the institution and the results of the applications are not monitored.","4":"Internal quality assurance mechanisms and defined processes covering all areas and processes in the institution are carried out systematically within the scope of a holistic quality management approach; The findings obtained from the implemented practices are monitored and the monitoring results are evaluated together with the stakeholders and improvements are made.","5":"Sustainable and integrated internal quality assurance practices, covering all areas and processes, in line with corporate objectives, have been adopted throughout the institution. The institution has innovative practices within the scope of quality management, and some of the practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ÙŠÙˆØ¬Ø¯ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù†Ø¸Ø§Ù… ÙˆØ¢Ù„ÙŠØ§Øª Ø¯Ø§Ø®Ù„ÙŠØ© Ù„Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©.","2":"ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¢Ù„ÙŠØ§Øª Ø¯Ø§Ø®Ù„ÙŠØ© Ù„Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©ØŒ Ù„ÙƒÙ† Ù‡Ø°Ù‡ Ø§Ù„Ø¢Ù„ÙŠØ§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª/Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª (Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ØŒ Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ±ØŒ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©ØŒ Ù†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø©).","3":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¢Ù„ÙŠØ§Øª Ø¯Ø§Ø®Ù„ÙŠØ© Ù„Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© (Ø§Ù„Ø¹Ù…Ù„ÙŠØ§ØªØŒ Ø¯ÙˆØ±Ø§Øª PDCAØŒ Ø§Ù„ÙˆØ§Ø¬Ø¨Ø§ØªØŒ Ø§Ù„Ø³Ù„Ø·Ø§Øª ÙˆØ§Ù„Ù…Ø³Ø¤ÙˆÙ„ÙŠØ§ØªØŒ Ø£Ø¯ÙˆØ§Øª Ø§Ù„Ø¬ÙˆØ¯Ø©) ØªØ