INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (11, 'A.2.3', 'Liderlik ve Kalite GÃ¼vencesi KÃ¼ltÃ¼rÃ¼', 'Culture of Leadership and Quality Assurance', 'Ø«Ù‚Ø§ÙØ© Ø§Ù„Ù‚ÙŠØ§Ø¯Ø© ÙˆØ¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda kalite gÃ¼vencesi kÃ¼ltÃ¼rÃ¼nÃ¼ destekleyen kurumsal kÃ¼ltÃ¼r ve liderlik yaklaÅŸÄ±mÄ± bulunmamaktadÄ±r.","2":"Kurumda kalite gÃ¼vencesi kÃ¼ltÃ¼rÃ¼nÃ¼ destekleyen kurumsal kÃ¼ltÃ¼r ve liderlik yaklaÅŸÄ±mÄ± oluÅŸturmak Ã¼zere planlar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± ve birimleri kapsamayan uygulamalar bulunmaktadÄ±r.","3":"Kurumda kalite gÃ¼vencesi kÃ¼ltÃ¼rÃ¼nÃ¼ destekleyen, tÃ¼m birimleri ve sÃ¼reÃ§leri kapsayan kurumsal kÃ¼ltÃ¼r ve liderlik anlayÄ±ÅŸÄ± bulunmakta olup; bu kapsamda gerÃ§ekleÅŸtirilen faaliyetlerden bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak tÃ¼m bu uygulamalar kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda yÃ¼rÃ¼tÃ¼lmemekte ve bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumda yÃ¼ksek kaliteyi kalÄ±cÄ± bir ÅŸekilde saÄŸlayan kurumsal kÃ¼ltÃ¼r ile kurumdaki deÄŸer ve beklentiler doÄŸrultusunda kalite Ã§alÄ±ÅŸmalarÄ±nÄ±n koordine edilmesini saÄŸlayan ve kalite sÃ¼reÃ§lerini sahiplenen liderlik anlayÄ±ÅŸÄ± bulunmaktadÄ±r. Liderlik ve kalite gÃ¼vencesi kÃ¼ltÃ¼rÃ¼, kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda izlenmekte, paydaÅŸlarla birlikte deÄŸerlendirilmekte ve izlem sonuÃ§larÄ±na gÃ¶re Ã¶nlem alÄ±nmaktadÄ±r.","5":"TÃ¼m birimleri ve sÃ¼reÃ§leri kapsayan, kurumsal amaÃ§lar doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ kurumsal kalite kÃ¼ltÃ¼rÃ¼ ve liderlik yaklaÅŸÄ±mÄ± kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun kalite kÃ¼ltÃ¼rÃ¼nÃ¼ gÃ¼Ã§lendirme ve liderlik yaklaÅŸÄ±mÄ± kapsamÄ±nda yenilikÃ§i uygulamalarÄ± bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no corporate culture and leadership approach that supports the culture of quality assurance in the institution.","2":"There are plans to create a corporate culture and leadership approach that supports a culture of quality assurance in the institution. However, there are no applications made in line with these plans, or there are applications that do not cover all areas and units.","3":"The institution has a corporate culture and leadership approach that supports the culture of quality assurance and covers all units and processes; Some results were obtained from the activities carried out in this context. However, all these practices are not carried out within the scope of holistic quality management in the institution and the results of these practices are not monitored.","4":"There is a corporate culture that ensures permanent high quality in the institution, and a leadership approach that ensures the coordination of quality studies in line with the values â€‹â€‹and expectations in the institution and embraces quality processes. Leadership and quality assurance culture is monitored within the scope of holistic quality management in the institution, evaluated together with stakeholders, and measures are taken according to the monitoring results.","5":"A sustainable and mature corporate quality culture and leadership approach, covering all units and processes, in line with corporate objectives, has been adopted throughout the institution; The institution has innovative practices within the scope of strengthening its quality culture and leadership approach, and some of the practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø«Ù‚Ø§ÙØ© Ù…Ø¤Ø³Ø³ÙŠØ© ÙˆÙ†Ù‡Ø¬ Ù‚ÙŠØ§Ø¯ÙŠ ÙŠØ¯Ø¹Ù… Ø«Ù‚Ø§ÙØ© Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· Ù„Ø®Ù„Ù‚ Ø«Ù‚Ø§ÙØ© Ù…Ø¤Ø³Ø³ÙŠØ© 