INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (12, 'A.3.1', 'Ä°Ã§ ve DÄ±ÅŸ PaydaÅŸlarÄ±n Kalite GÃ¼vencesi, EÄŸitim ve Ã–ÄŸretim, AraÅŸtÄ±rma ve GeliÅŸtirme, Toplumsal KatkÄ±, YÃ¶netim ve UluslararasÄ±laÅŸma SÃ¼reÃ§lerine KatÄ±lÄ±mÄ±', 'Participation of Internal and External Stakeholders in Quality Assurance, Education, R&D, Social Contribution, Management and Internationalization Processes', 'Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© Ø§Ù„Ø¯Ø§Ø®Ù„ÙŠÙˆÙ† (Ø§Ù„Ù…ÙˆØ¸ÙÙˆÙ† - Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ ÙˆØ§Ù„Ø¥Ø¯Ø§Ø±ÙŠÙˆÙ†)', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda yÃ¼rÃ¼tÃ¼len tÃ¼m sÃ¼reÃ§lere (kalite gÃ¼vencesi, eÄŸitim ve Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme, toplumsal katkÄ±, yÃ¶netim sistemi, uluslararasÄ±laÅŸma) paydaÅŸ katÄ±lÄ±mÄ±nÄ± saÄŸlayacak mekanizma ve uygulamalar bulunmamaktadÄ±r.","2":"Kurumda paydaÅŸlar belirlenmiÅŸ ve paydaÅŸ analizleri gerÃ§ekleÅŸtirilmiÅŸtir ve paydaÅŸ katÄ±lÄ±mÄ±na iliÅŸkin bazÄ± tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya mevcut uygulamalar bÃ¼tÃ¼n sÃ¼reÃ§leri/alanlarÄ±/paydaÅŸ gruplarÄ±nÄ± kapsamamaktadÄ±r.","3":"Kurumda yÃ¼rÃ¼tÃ¼len tÃ¼m sÃ¼reÃ§lerle iliÅŸkili olarak belirlenmiÅŸ olan paydaÅŸlarÄ±n sÃ¼reÃ§lere ve karar alma mekanizmalarÄ±na katÄ±lÄ±mÄ± saÄŸlanmÄ±ÅŸtÄ±r ve bu etkileÅŸimden bazÄ± uygulama sonuÃ§larÄ± elde edilmiÅŸtir. Ancak tÃ¼m bu uygulamalar kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda yÃ¼rÃ¼tÃ¼lmemektedir ve bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumdaki tÃ¼m sÃ¼reÃ§lere ve karar almalara paydaÅŸlarÄ±n katÄ±lÄ±mÄ± kurumdaki bÃ¼tÃ¼ncÃ¼l kalite yÃ¶netimi kapsamÄ±nda yÃ¼rÃ¼tÃ¼lmekte ve paydaÅŸ katÄ±lÄ±mÄ± uygulamalarÄ±ndan elde edilen bulgular izlenerek paydaÅŸlarla birlikte deÄŸerlendirilmekte ve izlem sonuÃ§larÄ±na gÃ¶re Ã¶nlem alÄ±nmaktadÄ±r.","5":"Kurumdaki tÃ¼m sÃ¼reÃ§lere ve karar almalara paydaÅŸlarÄ±n katÄ±lÄ±mÄ±, olgunlaÅŸmÄ±ÅŸ ve sÃ¼rdÃ¼rÃ¼lebilir uygulamalarla saÄŸlanarak kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun paydaÅŸ katÄ±lÄ±mÄ±nÄ± gÃ¼Ã§lendirmek Ã¼zere yenilikÃ§i uygulamalarÄ± bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no mechanisms and practices that will ensure stakeholder participation in all processes carried out in the institution (quality assurance, education and training, research and development, social contribution, management system, internationalization).","2":"Stakeholders have been identified and stakeholder analyzes have been carried out in the institution, and there are some defined processes for stakeholder participation. However, there are no practices made in line with these processes, or existing practices do not cover all processes/areas/stakeholder groups.","3":"The participation of stakeholders identified in relation to all processes carried out in the institution in the processes and decision-making mechanisms was ensured, and some implementation results were obtained from this interaction. However, all these practices are not carried out within the scope of holistic quality management in the institution and the results of these practices are not monitored.","4":"Participation of stakeholders in all processes and decision-making in the institution is carried out within the scope of holistic quality management in the institution, and the findings obtained from stakeholder participation practices are monitored and evaluated together with the stakeholders and precautions are taken according to the monitoring results.","5":"Participation of stakeholders in all processes and decision-making in the institution is ensured through mature and sustainable practices and adopted throughout the institution; The institution has innovative practices 