INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (14, 'A.4.1', 'UluslararasÄ±laÅŸma PolitikasÄ±', 'Internationalization Policy', 'Ø³ÙŠØ§Ø³Ø© Ø§Ù„ØªØ¯ÙˆÙŠÙ„', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda tanÄ±mlÄ± bir uluslararasÄ±laÅŸma politikasÄ± bulunmamaktadÄ±r.","2":"Kurumun tanÄ±mlÄ± uluslararasÄ±laÅŸma politikasÄ± bulunmaktadÄ±r. Ancak bu politika doÄŸrultusunda gerÃ§ekleÅŸtirilmiÅŸ uygulamalar bulunmamaktadÄ±r.","3":"Kurumun eÄŸitim ve Ã¶ÄŸretim, araÅŸtÄ±rma ve geliÅŸtirme ve toplumsal katkÄ± fonksiyonlarÄ±nÄ±n tÃ¼mÃ¼nÃ¼ dikkate alan uluslararasÄ±laÅŸma politikasÄ± doÄŸrultusunda bazÄ± uygulamalarÄ± bulunmaktadÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumun uluslararasÄ±laÅŸma politikasÄ± doÄŸrultusunda yapÄ±lan uygulamalar sistematik ve kurumun iÃ§ kalite gÃ¼vencesi sistemi ile uyumlu olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumun Ã¶zgÃ¼n uluslararasÄ±laÅŸma modeli kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun uluslararasÄ±laÅŸma modeli kapsamÄ±nda yenilikÃ§i uygulamalar bulunmakta, uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no defined internationalization policy in the institution.","2":"The institution has a defined internationalization policy. However, there are no practices implemented in line with this policy.","3":"The institution has some practices in line with its internationalization policy, which takes into account all education and training, research and development and social contribution functions, and some results have been obtained from these practices. However, the results of these practices are not monitored.","4":"Practices carried out in line with the institution''s internationalization policy are monitored systematically and in accordance with the institution''s internal quality assurance system, and measures are taken by evaluating them together with stakeholders.","5":"The institution''s unique internationalization model is adopted throughout the institution; There are innovative practices within the scope of the institution''s internationalization model, and some of the practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø³ÙŠØ§Ø³Ø© ØªØ¯ÙˆÙŠÙ„ Ù…Ø­Ø¯Ø¯Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù„Ø¯ÙŠÙ‡Ø§ Ø³ÙŠØ§Ø³Ø© ØªØ¯ÙˆÙŠÙ„ Ù…Ø­Ø¯Ø¯Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙŠØªÙ… ØªÙ†ÙÙŠØ°Ù‡Ø§ Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø³ÙŠØ§Ø³Ø©.","3":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ØªÙŠ ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø³ÙŠØ§Ø³Ø© Ø§Ù„ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ø®Ø§ØµØ© Ø¨Ù‡Ø§ØŒ ÙˆØ§Ù„ØªÙŠ ØªØ£Ø®Ø° ÙÙŠ Ø§Ù„Ø§Ø¹ØªØ¨Ø§Ø± Ø¬Ù…ÙŠØ¹ ÙˆØ¸Ø§Ø¦Ù Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ ÙˆØ§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙˆØ§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©ØŒ ÙˆÙ‚Ø¯ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ØªÙŠ ØªØªÙ… Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø³ÙŠØ§Ø³Ø© Ø§Ù„ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ø®Ø§ØµØ© Ø¨Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙˆÙÙ‚Ù‹Ø§ Ù„Ù†Ø¸Ø§Ù… Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø© Ø§Ù„Ø¯Ø§Ø®Ù„ÙŠ Ù„Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„ØªØ¯Ø§Ø¨ÙŠØ± Ù…Ù† Ø®Ù„Ø§Ù„ ØªÙ‚ÙŠÙŠÙ…Ù‡Ø§ Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©.","5":"ÙŠØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ù†Ù…ÙˆØ°Ø¬ Ø§Ù„ØªØ¯ÙˆÙŠÙ„ Ø§Ù„ÙØ±ÙŠØ¯ Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø› Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø¨ØªÙƒØ±Ø© Ø¶Ù…Ù† Ù†Ø·Ø§Ù‚ Ù†Ù…ÙˆØ°Ø¬ Ø§Ù„ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ø®Ø§Øµ Ø¨Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙŠØªÙ… Ø£Ø®Ø° Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙƒÙ…Ø«Ø§Ù„ Ù…Ù† Ù‚Ø¨Ù„ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aci