INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (15, 'A.4.2', 'UluslararasÄ±laÅŸma SÃ¼reÃ§lerinin YÃ¶netimi ve Organizasyonel YapÄ±sÄ±', 'Management and Organizational Structure of Internationalization Processes', 'Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ¯ÙˆÙŠÙ„', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun uluslararasÄ±laÅŸma sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±sÄ±na iliÅŸkin planlamalar bulunmamaktadÄ±r.","2":"Kurumun uluslararasÄ±laÅŸma sÃ¼reÃ§lerinin yÃ¶netim ve organizasyonel yapÄ±sÄ±na iliÅŸkin planlamalar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r.","3":"Kurumda uluslararasÄ±laÅŸma sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±sÄ± kurumsal tercihler yÃ¶nÃ¼nde uygulamaya konularak bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§lar izlenmemektedir.","4":"Kurumda uluslararasÄ±laÅŸma sÃ¼reÃ§lerinin yÃ¶netimi ile iliÅŸkili sonuÃ§lar ve paydaÅŸ gÃ¶rÃ¼ÅŸleri sistematik olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda tÃ¼m birimleri/alanlarÄ± kapsayan uluslararasÄ±laÅŸma yÃ¶netimi, kurumsal amaÃ§lar doÄŸrultusunda bÃ¼tÃ¼nleÅŸtirici, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no plans regarding the management and organizational structure of the institution''s internationalization processes.","2":"There are plans regarding the management and organizational structure of the institution''s internationalization processes. However, there are no practices made in line with these plans.","3":"Some results have been achieved by implementing the management and organizational structure of internationalization processes in the institution in line with institutional preferences. However, these results are not monitored.","4":"The results and stakeholder opinions related to the management of internationalization processes in the institution are systematically monitored and measures are taken by evaluating them together with the stakeholders.","5":"Internationalization management, covering all units/areas in the institution, has been adopted and secured throughout the institution with integrative, sustainable and mature practices in line with corporate objectives; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø®Ø·Ø· ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· ØªØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø·.","3":"ÙˆÙ‚Ø¯ ØªÙ… ØªØ­Ù‚ÙŠÙ‚ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ø®Ù„Ø§Ù„ ØªÙ†ÙÙŠØ° Ø§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¥Ø¯Ø§Ø±ÙŠ ÙˆØ§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ¯ÙˆÙŠÙ„ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø§Ù„ØªÙØ¶ÙŠÙ„Ø§Øª Ø§Ù„Ù…Ø¤Ø³Ø³ÙŠØ©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù‡Ø°Ù‡ Ø§Ù„Ù†ØªØ§Ø¦Ø¬.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù†ØªØ§Ø¦Ø¬ ÙˆØ¢Ø±Ø§Ø¡ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ø¥Ø¯Ø§Ø±Ø© Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ¯ÙˆÙŠÙ„ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„ØªØ¯Ø§Ø¨ÙŠØ± Ù…Ù† Ø®Ù„Ø§Ù„ ØªÙ‚ÙŠÙŠÙ…Ù‡Ø§ Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©.","5":"ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„ØªØ¯ÙˆÙŠÙ„ØŒ Ø§Ù„ØªÙŠ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„ÙˆØ­Ø¯Ø§Øª/Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆØªØ£Ù…ÙŠÙ†Ù‡Ø§ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…ØªÙƒØ§Ù