INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (16, 'A.4.3', 'UluslararasÄ±laÅŸma KaynaklarÄ±', 'Internationalization Resources', 'Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„ØªØ¯ÙˆÙŠÙ„', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun uluslararasÄ±laÅŸma faaliyetlerini sÃ¼rdÃ¼rebilmesi iÃ§in uygun nitelik ve nicelikte fiziki, teknik ve mali kaynaklarÄ± bulunmamaktadÄ±r.","2":"Kurumun uluslararasÄ±laÅŸma faaliyetlerini sÃ¼rdÃ¼rebilmek iÃ§in uygun nitelik ve nicelikte fiziki, teknik ve mali kaynaklarÄ±n oluÅŸturulmasÄ±na yÃ¶nelik planlar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r .","3":"Kurumun uluslararasÄ±laÅŸma faaliyetlerini sÃ¼rdÃ¼rebilmek iÃ§in uygun nitelik ve nicelikte fiziki, teknik ve mali kaynaklar saÄŸlanmaktadÄ±r. Ancak bu kaynaklarÄ±n kullanÄ±mÄ±na yÃ¶nelik sonuÃ§lar izlenmemektedir.","4":"Kurumda fiziki, teknik ve mali kaynaklar, uluslararasÄ±laÅŸma faaliyetlerini destekleyecek ÅŸekilde yÃ¶netilmektedir. TÃ¼m bu uygulamalardan elde edilen bulgular, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmakta ve ihtiyaÃ§lar/talepler doÄŸrultusunda kaynaklar Ã§eÅŸitlendirilmektedir.","5":"Kurumda uygun nicelik ve nitelikte fiziki, teknik ve mali kaynaklar, kurumsal amaÃ§lar (uluslararasÄ±laÅŸma politikasÄ± ve stratejisi) doÄŸrultusunda ve sÃ¼rdÃ¼rÃ¼lebilir ÅŸekilde yÃ¶netilmektedir; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have physical, technical and financial resources of appropriate quality and quantity to continue its internationalization activities.","2":"There are plans to create physical, technical and financial resources of appropriate quality and quantity in order to continue the internationalization activities of the institution. However, there are no practices made in line with these plans.","3":"Physical, technical and financial resources of appropriate quality and quantity are provided in order to continue the internationalization activities of the institution. However, the results of the use of these resources are not monitored.","4":"The institution''s physical, technical and financial resources are managed to support internationalization activities. The findings obtained from all these applications are systematically monitored and the monitoring results are evaluated together with the stakeholders, precautions are taken and resources are diversified in line with the needs/demands.","5":"In the institution, physical, technical and financial resources of appropriate quantity and quality are managed in a sustainable manner in line with corporate objectives (internationalization policy and strategy); The institution has many unique and innovative applications in this context, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ø¯ÙŠØ© ÙˆØ§Ù„ØªÙ‚Ù†ÙŠØ© ÙˆØ§Ù„Ù…Ø§Ù„ÙŠØ© Ø°Ø§Øª Ø§Ù„Ø¬ÙˆØ¯Ø© ÙˆØ§Ù„ÙƒÙ…ÙŠØ© Ø§Ù„Ù…Ù†Ø§Ø³Ø¨Ø© Ù„Ù…ÙˆØ§ØµÙ„Ø© Ø£Ù†Ø´Ø·ØªÙ‡Ø§ Ø§Ù„Ø¯ÙˆÙ„ÙŠØ©.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· Ù„Ø¥Ù†Ø´Ø§Ø¡ Ù…ÙˆØ§Ø±Ø¯ Ù…Ø§Ø¯ÙŠØ© ÙˆØªÙ‚Ù†ÙŠØ© ÙˆÙ…Ø§Ù„ÙŠØ© Ø°Ø§Øª Ù†ÙˆØ¹ÙŠØ© ÙˆÙƒÙ…ÙŠØ© Ù…Ù†Ø§Ø³Ø¨Ø© Ù…Ù† Ø£Ø¬Ù„ Ù…ÙˆØ§ØµÙ„Ø© Ø£Ù†Ø´Ø·Ø© ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø·.","3":"ÙŠØªÙ… ØªÙˆÙÙŠØ± Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ø¯ÙŠØ© ÙˆØ§Ù„ØªÙ‚Ù†ÙŠØ© ÙˆØ§Ù„Ù…Ø§Ù„ÙŠØ© Ø°Ø§Øª Ø§Ù„Ø¬ÙˆØ¯Ø© ÙˆØ§Ù„ÙƒÙ…ÙŠØ© Ø§Ù„Ù…Ù†Ø§Ø³Ø¨Ø© Ù…Ù† Ø£Ø¬Ù„ Ù…ÙˆØ§ØµÙ„Ø© Ø£Ù†Ø´Ø·Ø© ØªØ¯ÙˆÙŠÙ„ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ø§Ø³ØªØ®Ø¯Ø§Ù… Ù‡Ø°Ù‡ Ø§Ù„Ù…ÙˆØ§Ø±Ø¯.","4":"ØªØªÙ… Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø