INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (17, 'A.4.4', 'UluslararasÄ±laÅŸma PerformansÄ±nÄ±n Ä°zlenmesi ve Ä°yileÅŸtirilmesi', 'Monitoring and Improving Internationalization Performance', 'Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªØ­Ø³ÙŠÙ† Ø£Ø¯Ø§Ø¡ Ø§Ù„ØªØ¯ÙˆÙŠÙ„', 1, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda uluslararasÄ±laÅŸma performansÄ±nÄ±n izlenmesine ve deÄŸerlendirmesine yÃ¶nelik planlamalar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmamaktadÄ±r.","2":"Kurumda uluslararasÄ±laÅŸma performansÄ±nÄ±n izlenmesine ve deÄŸerlendirmesine yÃ¶nelik planlamalar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu planlar ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r.","3":"Kurumda uluslararasÄ±laÅŸma performansÄ±nÄ±n izlenmesine ve deÄŸerlendirmesine yÃ¶nelik uygulamalar tÃ¼m alanlarÄ± kapsar ÅŸekilde yÃ¼rÃ¼tÃ¼lmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir veya karar alma sÃ¼reÃ§lerinde kullanÄ±lmamaktadÄ±r.","4":"Kurumda uluslararasÄ±laÅŸma hedefleri doÄŸrultusunda Ã§alÄ±ÅŸma yapan birimlerin(Komisyon, koordinatÃ¶rlÃ¼k, iÅŸ birliÄŸi yapÄ±lan merkez vb.) uluslararasÄ±laÅŸma performansÄ± izlenerek deÄŸerlendirilmekte ve karar alma sÃ¼reÃ§lerinde kullanÄ±lmaktadÄ±r. Buna iliÅŸkin uygulamalar dÃ¼zenli olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, kurumsal amaÃ§lar (uluslararasÄ±laÅŸma politikasÄ±, hedefleri, stratejisi) ve uluslararasÄ±laÅŸma hedefleri doÄŸrultusunda Ã§alÄ±ÅŸma yapan birimlerin uluslararasÄ±laÅŸma performansÄ±nÄ±n izlenmesi ve deÄŸerlendirilmesine iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r. Kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no plans or defined processes for monitoring and evaluating internationalization performance in the institution.","2":"The institution has plans and defined processes for monitoring and evaluating internationalization performance. However, there are no practices made in line with these plans and processes.","3":"Practices for monitoring and evaluating internationalization performance in the institution are carried out in a way that covers all areas. However, the results of these practices are not monitored or used in decision-making processes.","4":"The internationalization performance of the units (Commission, coordinatorship, cooperating center, etc.) working in line with the internationalization targets in the institution is monitored and evaluated and used in decision-making processes. Related practices are monitored regularly and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In the institution, sustainable and mature practices regarding the monitoring and evaluation of the internationalization performance of the units working in line with the institutional goals (internationalization policy, goals, strategy) and internationalization targets have been adopted and secured throughout the institution. The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø®Ø·Ø· Ø£Ùˆ Ø¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø±ØµØ¯ ÙˆØªÙ‚ÙŠÙŠÙ… Ø£Ø¯Ø§Ø¡ Ø§Ù„ØªØ¯ÙˆÙŠÙ„ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø®Ø·Ø· ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø±ØµØ¯ ÙˆØªÙ‚ÙŠÙŠÙ… Ø£Ø¯Ø§Ø¡ Ø§Ù„ØªØ¯ÙˆÙŠÙ„. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø· ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§Øª.","3":"ÙŠØªÙ… ØªÙ†ÙÙŠØ° Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªÙ‚ÙŠÙŠÙ… Ø£Ø¯Ø§Ø¡ Ø§Ù„ØªØ¯ÙˆÙŠÙ„ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø·Ø±ÙŠÙ‚Ø© ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ 