INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (18, 'B.1.1', 'Program TasarÄ±m ve OnayÄ±', 'Program Design and Approval', 'ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda programÄ±n tasarÄ±mÄ± ve onayÄ±na iliÅŸkin tanÄ±mlÄ± ve sistematik sÃ¼reÃ§ler bulunmamaktadÄ±r.","2":"Kurumda programÄ±n tasar Ä±mÄ± ve onayÄ±na iliÅŸkin tanÄ±mlÄ± ve sistematik sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu sÃ¼reÃ§ler tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumda programÄ±n tasarÄ±mÄ± ve onayÄ±na iliÅŸkin tanÄ±mlÄ± sÃ¼reÃ§ler doÄŸrultusunda uygulamalar gerÃ§ekleÅŸtirilmiÅŸ ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ±nÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"PaydaÅŸlarÄ±n katÄ±lÄ±mÄ±yla programÄ±n tasarÄ±mÄ± ve onayÄ±na iliÅŸkin uygulamalar sistematik olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"PaydaÅŸlarÄ±n katÄ±lÄ±mÄ±yla programÄ±n tasarÄ±mÄ± ve onayÄ±na iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; bu kapsamda kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmaktadÄ±r ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no defined and systematic processes in the institution regarding the design and approval of the program.","2":"The institution has defined and systematic processes for program design and approval. However, these processes do not cover all areas.","3":"Applications have been carried out in line with the defined processes regarding the design and approval of the program in the institution, and some results have been obtained from these applications. However, the results of these practices are not monitored.","4":"With the participation of stakeholders, practices regarding the design and approval of the program are systematically monitored and measures are taken by evaluating them together with the stakeholders.","5":"Sustainable and mature practices for program design and approval with stakeholder participation are adopted throughout the institution; In this context, the institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© ÙˆÙ…Ù†Ù‡Ø¬ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© ÙˆÙ…Ù†Ù‡Ø¬ÙŠØ© Ù„ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡Ø§. Ø¥Ù„Ø§ Ø£Ù† Ù‡Ø°Ù‡ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ØªÙ… ØªÙ†ÙÙŠØ° Ø§Ù„Ø·Ù„Ø¨Ø§Øª Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…Ø­Ø¯Ø¯Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ÙˆØ¨Ù…Ø´Ø§Ø±ÙƒØ© Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©ØŒ ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡ Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„ØªØ¯Ø§Ø¨ÙŠØ± Ù…Ù† Ø®Ù„Ø§Ù„ ØªÙ‚ÙŠÙŠÙ…Ù‡Ø§ Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©.","5":"ÙŠØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø© Ù„ØªØµÙ…ÙŠÙ… Ø§Ù„Ø¨Ø±Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…ÙˆØ§ÙÙ‚Ø© Ø¹Ù„ÙŠÙ‡Ø§ Ø¨Ù…Ø´Ø§Ø±ÙƒØ© Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø› ÙˆÙÙŠ Ù‡Ø°Ø§ Ø§Ù„Ø³ÙŠØ§Ù‚ØŒ ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ø¹Ø¯ÙŠØ¯ Ù…Ù† Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø§Ù„ÙØ±ÙŠØ¯Ø© ÙˆØ§Ù„Ù…Ø¨ØªÙƒØ±Ø©ØŒ ÙˆØ¨Ø¹Ø¶ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª ØªØªØ®Ø° Ù…Ø«Ø§Ù„Ø§Ù‹ Ù…Ù† Ù‚Ø¨Ù„ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰."}'::jsonb, NULL, NULL, '{"bgs_