INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (21, 'B.1.4', 'ProgramÄ±n YapÄ±sÄ± ve Ders DaÄŸÄ±lÄ±m Dengesi', 'Structure of the Program and Course Distribution Balance', 'Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØªÙˆØ§Ø²Ù† ØªÙˆØ²ÙŠØ¹ Ø§Ù„Ø¯ÙˆØ±Ø©', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"ProgramÄ±n yapÄ±sÄ± ve ders daÄŸÄ±lÄ±m dengesi programda hiÃ§bir alanda dikkate alÄ±nmamÄ±ÅŸtÄ±r.","2":"ProgramÄ±n yapÄ±sÄ± ve ders daÄŸÄ±lÄ±m dengesine iliÅŸkin planlamalar bulunmaktadÄ±r. Ancak bu uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Programda program ve ders bilgi paketleri, yapÄ± ve ders daÄŸÄ±lÄ±m dengesi (alan ve meslek bilgisi ile genel kÃ¼ltÃ¼r dersleri dengesi, kÃ¼ltÃ¼rel derinlik kazanma, farklÄ± disiplinleri tanÄ±ma imkÃ¢nlarÄ± vb.) gÃ¶zetilerek hazÄ±rlanmÄ±ÅŸtÄ±r. Ancak bu uygulamalarÄ±n sonuÃ§larÄ±nÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"Program yapÄ±sÄ± ve dengesine iliÅŸkin uygulamalar tÃ¼m alanlarda, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlem alÄ±nmakta ve sÃ¼rekli olarak gÃ¼ncellenmektedir.","5":"Program yapÄ±sÄ± ve dengesine iliÅŸkin kurumsal amaÃ§lar (eÄŸitim-Ã¶ÄŸretim politikasÄ±) doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar tÃ¼m birimlerde benimsenmiÅŸtir. Kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The structure of the program and the balance of course distribution are not taken into consideration in any area of â€‹â€‹the program.","2":"There are plans regarding the structure of the program and the balance of course distribution. However, these applications do not cover all areas.","3":"The program and course information packages in the program have been prepared by taking into account the balance of structure and course distribution (balance of field and professional knowledge and general culture courses, gaining cultural depth, opportunities to get to know different disciplines, etc.). However, the results of these practices are not monitored.","4":"Practices regarding program structure and balance are monitored systematically in all areas, and the monitoring results are evaluated together with stakeholders, precautions are taken and constantly updated.","5":"In line with institutional goals (education-training policy) regarding program structure and balance, sustainable and mature practices have been adopted in all units. The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ÙŠØ¤Ø®Ø° Ø¨Ø¹ÙŠÙ† Ø§Ù„Ø§Ø¹ØªØ¨Ø§Ø± Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØªÙˆØ§Ø²Ù† ØªÙˆØ²ÙŠØ¹ Ø§Ù„Ù…Ù‚Ø±Ø±Ø§Øª ÙÙŠ Ø£ÙŠ Ù…Ø¬Ø§Ù„ Ù…Ù† Ù…Ø¬Ø§Ù„Ø§Øª Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· ØªØªØ¹Ù„Ù‚ Ø¨Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØªÙˆØ§Ø²Ù† ØªÙˆØ²ÙŠØ¹ Ø§Ù„Ø¯ÙˆØ±Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ ÙØ¥Ù† Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ØªÙ… Ø¥Ø¹Ø¯Ø§Ø¯ Ø§Ù„Ø­Ø²Ù… Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§ØªÙŠØ© Ø§Ù„Ø®Ø§ØµØ© Ø¨Ø§Ù„Ø¨Ø±Ø§Ù…Ø¬ ÙˆØ§Ù„Ù…Ù‚Ø±Ø±Ø§Øª ÙÙŠ Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ Ù…Ø¹ Ù…Ø±Ø§Ø¹Ø§Ø© Ø§Ù„ØªÙˆØ§Ø²Ù† ÙÙŠ Ø§Ù„Ù‡ÙŠÙƒÙ„ÙŠØ© ÙˆØªÙˆØ²ÙŠØ¹ Ø§Ù„Ù…Ù‚Ø±Ø±Ø§Øª (ØªÙˆØ§Ø²Ù† Ø§Ù„Ù…Ø¹Ø±ÙØ© Ø§Ù„Ù…ÙŠØ¯Ø§Ù†ÙŠØ© ÙˆØ§Ù„Ù…Ù‡Ù†ÙŠØ© ÙˆØ¯ÙˆØ±Ø§Øª Ø§Ù„Ø«Ù‚Ø§ÙØ© Ø§Ù„Ø¹Ø§Ù…Ø©ØŒ Ø§ÙƒØªØ³Ø§Ø¨ Ø§Ù„Ø¹Ù…Ù‚ Ø§Ù„Ø«Ù‚Ø§ÙÙŠØŒ ÙØ±Øµ Ø§Ù„ØªØ¹Ø±Ù Ø¹Ù„Ù‰ Ø§Ù„ØªØ®ØµØµØ§Øª Ø§Ù„Ù…Ø®ØªÙ„ÙØ©ØŒ ÙˆÙ…Ø§ Ø¥Ù„Ù‰ Ø°Ù„Ùƒ). ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬ ÙˆØªÙˆØ§Ø²Ù†Ù‡ Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§ØªØŒ ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©ØŒ ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø