INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (29, 'B.3.4', 'Akademik DanÄ±ÅŸmanlÄ±k', 'Academic Advising', 'Ø§Ù„Ø¥Ø±Ø´Ø§Ø¯ Ø§Ù„Ø£ÙƒØ§Ø¯ÙŠÙ…ÙŠ', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda tanÄ±mlÄ± bir akademik danÄ±ÅŸmanlÄ±k sÃ¼reci bulunmamaktadÄ±r.","2":"Kurumda tanÄ±mlÄ± bir akademik danÄ±ÅŸmanlÄ±k sÃ¼reci bulunmaktadÄ±r. Ancak hiÃ§ uygulama yoktur veya tÃ¼m alanlarÄ± kapsamayan uygulamalar vardÄ±r.","3":"Kurumda akademik danÄ±ÅŸmanlÄ±k uygulamalarÄ± vardÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§larÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"Kurumda akademik danÄ±ÅŸmanlÄ±ÄŸa iliÅŸkin yÃ¼rÃ¼tÃ¼len uygulamalardan elde edilen bulgular, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumsal amaÃ§lar doÄŸrultusunda ve sÃ¼rdÃ¼rÃ¼lebilir ÅŸekilde yÃ¼rÃ¼tÃ¼len akademik danÄ±ÅŸmanlÄ±ÄŸa iliÅŸkin olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no defined academic counseling process in the institution.","2":"The institution has a defined academic consultancy process. However, there are no applications or there are applications that do not cover all areas.","3":"The institution has academic consultancy practices and some results have been obtained from these practices. However, these results are not monitored.","4":"The findings obtained from the academic consultancy practices carried out in the institution are systematically monitored and the monitoring results are evaluated together with the stakeholders and precautions are taken."