INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (30, 'B.4.1', 'Atama, YÃ¼kseltme ve GÃ¶revlendirme Kriterleri', 'Appointment, Promotion and Assignment Criteria', 'Ù…Ø¹Ø§ÙŠÙŠØ± Ø§Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØ§Ù„ØªØ¹ÙŠÙŠÙ†', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun atama, yÃ¼kseltme ve ders gÃ¶revlendirme kriterleri ve sÃ¼reÃ§leri tanÄ±mlanmamÄ±ÅŸtÄ±r.","2":"Kurumun atama, yÃ¼kseltme ve ders gÃ¶revlendirme kriterleri tanÄ±mlanmÄ±ÅŸ; ancak planlamada alana Ã¶zgÃ¼ ihtiyaÃ§lar irdelenmemiÅŸtir.","3":"Kurumun tÃ¼m alanlar iÃ§in tanÄ±mlÄ± ve paydaÅŸlarca bilinen atama, yÃ¼kseltme ve ders gÃ¶revlendirme kriterleri uygulanmakta ve karar almalarda (eÄŸitim-Ã¶ÄŸretim kadrosunun iÅŸe alÄ±nmasÄ±, atanmasÄ±, yÃ¼kseltilmesi ve ders gÃ¶revlendirmeleri vb.) kullanÄ±lmaktadÄ±r. Ancak bu uygulamalarÄ±n sonuÃ§larÄ±nÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"Atama, yÃ¼kseltme ve ders gÃ¶revlendirmesine iliÅŸkin uygulanan kriterlerin sonuÃ§larÄ±, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"TÃ¼m alanlarda atama, yÃ¼kseltme ve ders gÃ¶revlendirmesine iliÅŸkin kurumsal amaÃ§lar doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution''s appointment, promotion and course assignment criteria and processes are not defined.","2":"The institution''s appointment, promotion and course assignment criteria are defined; However, site-specific needs were not examined in the planning.","3":"The institution''s appointment, promotion and course assignment criteria, defined for all fields and known to stakeholders, are applied and used in decision-making (recruitment, appointment, promotion and course assignments of teaching staff, etc.). However, the results of these practices are not monitored.","4":"The results of the criteria applied for appointment, promotion and course assignment are systematically monitored and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"In line with institutional objectives regarding appointment, promotion and course assignment in all areas, sustainable and mature practices have been adopted throughout the institution; The institution has many unique and innovative applications in this context, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ù… ÙŠØªÙ… ØªØ­Ø¯ÙŠØ¯ Ù…Ø¹Ø§ÙŠÙŠØ± ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØªØ¹ÙŠÙŠÙ† Ø§Ù„Ù…Ù‚Ø±Ø± Ø§Ù„Ø¯Ø±Ø§Ø³ÙŠ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"ÙŠØªÙ… ØªØ­Ø¯ÙŠØ¯ Ù…Ø¹Ø§ÙŠÙŠØ± Ø§Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØªØ¹ÙŠÙŠÙ† Ø§Ù„Ø¯ÙˆØ±Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø› ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ù… ÙŠØªÙ… ÙØ­Øµ Ø§Ù„Ø§Ø­ØªÙŠØ§Ø¬Ø§Øª Ø§Ù„Ø®Ø§ØµØ© Ø¨Ø§Ù„Ù…ÙˆÙ‚Ø¹ ÙÙŠ Ø§Ù„ØªØ®Ø·ÙŠØ·.","3":"ÙŠØªÙ… ØªØ·Ø¨ÙŠÙ‚ Ù…Ø¹Ø§ÙŠÙŠØ± Ø§Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØªØ¹ÙŠÙŠÙ† Ø§Ù„Ù…Ù‚Ø±Ø±Ø§Øª Ø§Ù„Ø¯Ø±Ø§Ø³ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆØ§Ù„Ù…Ø­Ø¯Ø¯Ø© Ù„Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙˆØ§Ù„Ù…Ø¹Ø±ÙˆÙØ© Ù„Ø¯Ù‰ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©ØŒ ÙˆØ§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø± (Ø§Ù„ØªÙˆØ¸ÙŠÙ ÙˆØ§Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØªØ¹ÙŠÙŠÙ† Ø§Ù„Ù…Ù‚Ø±Ø±Ø§Øª Ø§Ù„Ø¯Ø±Ø§Ø³ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ØŒ ÙˆÙ…Ø§ Ø¥Ù„Ù‰ Ø°Ù„Ùƒ). ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø¹Ø§ÙŠÙŠØ± Ø§Ù„Ù…Ø·Ø¨Ù‚Ø© Ù„Ù„ØªØ¹ÙŠÙŠÙ† ÙˆØ§Ù„ØªØ±Ù‚ÙŠØ© ÙˆØªØ¹ÙŠÙŠÙ† Ø§Ù„Ø¯ÙˆØ±Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©."