INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (31, 'B.4.2', 'Ã–ÄŸretim YetkinliÄŸi', 'Teaching Competence', 'Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ÙŠØ©', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun Ã¶ÄŸretim elemanlarÄ±nÄ±n Ã¶ÄŸretim yetkinliÄŸini geliÅŸtirmek Ã¼zere planlamalar bulunmamaktadÄ±r.","2":"Kurumun Ã¶ÄŸretim elemanlarÄ±nÄ±n yenilikÃ§i yaklaÅŸÄ±mlar, materyal geliÅŸtirme, yetkinlik kazandÄ±rma ve kalite gÃ¼vence sistemi gibi Ã¶ÄŸretim yetkinliklerinin geliÅŸtirilmesine iliÅŸkin planlar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya kurumun tÃ¼mÃ¼nÃ¼ kapsamayan bazÄ± uygulamalar (eÄŸiticilerin eÄŸitimi etkinlikleri) bulunmaktadÄ±r.","3":"Kurumun Ã¶ÄŸretim elemanlarÄ±nÄ±n Ã¶ÄŸretim yetkinliÄŸini geliÅŸtirmek Ã¼zere uygulamalar vardÄ±r ve bunlar tÃ¼m alanlarÄ± kapsamaktadÄ±r. Ancak bu uygulamalarÄ±n sonuÃ§larÄ±nÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"Kurumun Ã¶ÄŸretim elemanlarÄ±nÄ±n Ã¶ÄŸretim yetkinliÄŸini geliÅŸtirmek Ã¼zere gerÃ§ekleÅŸtirilen uygulamalardan elde edilen bulgular sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Ã–ÄŸretim elemanlarÄ±nÄ±n kurumsal amaÃ§lar doÄŸrultusunda Ã¶ÄŸretim yetkinliklerinin geliÅŸimine iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no plans to improve the teaching competence of the institution''s faculty members.","2":"There are plans to develop the teaching competencies of the institution''s faculty members, such as innovative approaches, material development, competency acquisition and quality assurance system. However, there are no practices made in line with these plans, or there are some practices (training of trainers activities) that do not cover the entire institution.","3":"There are practices to improve the teaching competence of the institution''s faculty members and these cover all areas. However, the results of these practices are not monitored.","4":"The findings obtained from the practices carried out to improve the teaching competence of the institution''s faculty members are systematically monitored and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"Sustainable and mature practices regarding the development of teaching competencies of faculty members in line with institutional goals have been adopted throughout the institution; The institution has many unique and innovative applications in this context, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø®Ø·Ø· Ù„ØªØ­Ø³ÙŠÙ† Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ Ø¨Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· Ù„ØªØ·ÙˆÙŠØ± Ø§Ù„ÙƒÙØ§Ø¡Ø§Øª Ø§Ù„ØªØ¯Ø±ÙŠØ³ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ Ø¨Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ Ù…Ø«Ù„ Ø§Ù„Ø£Ø³Ø§Ù„ÙŠØ¨ Ø§Ù„Ù…Ø¨ØªÙƒØ±Ø©ØŒ ÙˆØªØ·ÙˆÙŠØ± Ø§Ù„Ù…ÙˆØ§Ø¯ØŒ ÙˆØ§ÙƒØªØ³Ø§Ø¨ Ø§Ù„ÙƒÙØ§Ø¡Ø§ØªØŒ ÙˆÙ†Ø¸Ø§Ù… Ø¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©. Ø¥Ù„Ø§ Ø£Ù†Ù‡ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø·ØŒ Ø£Ùˆ Ø£Ù† Ù‡Ù†Ø§Ùƒ Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª (Ø£Ù†Ø´Ø·Ø© ØªØ¯Ø±ÙŠØ¨ Ø§Ù„Ù…Ø¯Ø±Ø¨ÙŠÙ†) Ù„Ø§ ØªØºØ·ÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø£ÙƒÙ…Ù„Ù‡Ø§.","3":"Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„ØªØ­Ø³ÙŠÙ† Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ Ø¨Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙ‡ÙŠ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ø§Ù„ØªÙŠ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„ÙŠÙ‡Ø§ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª 