INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (32, 'B.4.3', 'EÄŸitim Faaliyetlerine YÃ¶nelik TeÅŸvik ve Ã–dÃ¼llendirme', 'Incentive and Reward for Educational Activities', 'Ø­ÙˆØ§ÙØ² ÙˆÙ…ÙƒØ§ÙØ¢Øª Ù„Ù„Ø£Ù†Ø´Ø·Ø© Ø§Ù„ØªØ¹Ù„ÙŠÙ…ÙŠØ©', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Ã–ÄŸretim kadrosuna yÃ¶nelik teÅŸvik ve Ã¶dÃ¼llendirilme mekanizmalarÄ± bulunmamaktadÄ±r.","2":"Ã–ÄŸretim kadrosunu teÅŸvik ve Ã¶dÃ¼llendirme mekanizmalarÄ±nÄ±n oluÅŸturulmasÄ±na yÃ¶nelik planlar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamayan bazÄ± uygulamalar bulunmaktadÄ±r.","3":"Kurumun Ã¶ÄŸretim kadrosunu teÅŸvik etme ve Ã¶dÃ¼llendirme uygulamalarÄ± Ã¶ÄŸretim elemanlarÄ±nÄ±n yetkinlikleri dikkate alÄ±narak adil ve ÅŸeffaf ÅŸekilde sÃ¼rdÃ¼rÃ¼lmektedir ve bunlar tÃ¼m alanlarÄ± kapsamaktadÄ±r. Ancak uygulama sonuÃ§larÄ± izlenmemektedir.","4":"Kurumun Ã¶ÄŸretim kadrosunun teÅŸvik etme ve Ã¶dÃ¼llendirmeye iliÅŸkin uygulamalardan elde edilen bulgular sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Ã–ÄŸretim kadrosunu, kurumsal amaÃ§lar doÄŸrultusunda teÅŸvik etme ve Ã¶dÃ¼llendirmeye iliÅŸkin, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no incentive and reward mechanisms for teaching staff.","2":"There are plans to create incentive and reward mechanisms for teaching staff. However, there are no applications made in line with these plans, or there are some applications that do not cover all areas.","3":"The institution''s practices of encouraging and rewarding its teaching staff are carried out in a fair and transparent manner, taking into account the competencies of the teaching staff, and these cover all areas. However, the application results are not monitored.","4":"The findings obtained from the institution''s practices regarding encouraging and rewarding the teaching staff are systematically monitored and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"Sustainable and mature practices for encouraging and rewarding faculty in line with institutional goals have been adopted throughout the institution; The institution has many unique and innovative applications in this context, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¢Ù„ÙŠØ§Øª Ø­ÙˆØ§ÙØ² ÙˆÙ…ÙƒØ§ÙØ¢Øª Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· Ù„Ø¥Ù†Ø´Ø§Ø¡ Ø¢Ù„ÙŠØ§Øª Ø§Ù„Ø­ÙˆØ§ÙØ² ÙˆØ§Ù„Ù…ÙƒØ§ÙØ¢Øª Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ø·Ù„Ø¨Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø·ØŒ Ø£Ùˆ Ø£Ù† Ù‡Ù†Ø§Ùƒ Ø¨Ø¹Ø¶ Ø§Ù„Ø·Ù„Ø¨Ø§Øª Ø§Ù„ØªÙŠ Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ØªØªÙ… Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠ ØªØ´Ø¬ÙŠØ¹ ÙˆÙ…ÙƒØ§ÙØ£Ø© Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ Ù„Ø¯ÙŠÙ‡Ø§ Ø¨Ø·Ø±ÙŠÙ‚Ø© Ø¹Ø§Ø¯Ù„Ø© ÙˆØ´ÙØ§ÙØ©ØŒ Ù…Ø¹ Ù…Ø±Ø§Ø¹Ø§Ø© ÙƒÙØ§Ø¡Ø§Øª Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ØŒ ÙˆØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ø§Ù„ØªÙŠ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„ÙŠÙ‡Ø§ Ù…Ù† Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨ØªØ´Ø¬ÙŠØ¹ ÙˆÙ…ÙƒØ§ÙØ£Ø© Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠ ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø© Ù„ØªØ´Ø¬ÙŠØ¹ ÙˆÙ…ÙƒØ§ÙØ£Ø© 