INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (38, 'B.6.1', 'Program Ã‡Ä±ktÄ±larÄ±nÄ±n Ä°zlenmesi ve GÃ¼ncellenmesi', 'Monitoring and Updating Program Outputs', 'Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªØ­Ø¯ÙŠØ« Ù…Ø®Ø±Ø¬Ø§Øª Ø§Ù„Ø¨Ø±Ù†Ø§Ù…Ø¬', 2, NULL, '2026-05-13T02:30:32.353681', '{"1":"Program Ã§Ä±ktÄ±larÄ±nÄ±n izlenmesine ve gÃ¼ncellenmesine iliÅŸkin herhangi bir mekanizma bulunmamaktadÄ±r.","2":"Program Ã§Ä±ktÄ±larÄ±nÄ±n izlenmesine ve gÃ¼ncellenmesine iliÅŸkin mekanizmalar (tanÄ±mlÄ± sÃ¼reÃ§ler ve performans gÃ¶stergeleri) oluÅŸturulmuÅŸtur. Ancak hiÃ§bir uygulama bulunmamaktadÄ±r.","3":"Kurumda program Ã§Ä±ktÄ±larÄ±nÄ±n izlenmesine iliÅŸkin uygulamalar gerÃ§ekleÅŸtirilmiÅŸ ve bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§larÄ±n deÄŸerlendirilmesi, karar almalarda ve gÃ¼ncellemelerde kullanÄ±lmasÄ± gerÃ§ekleÅŸtirilmemiÅŸtir.","4":"Kurumda program Ã§Ä±ktÄ±larÄ± sistematik olarak (yÄ±llÄ±k ve program sÃ¼resinin sonunda periyodik olarak) ve kurumsal amaÃ§lar doÄŸrultusunda (eÄŸitim-Ã¶ÄŸretim politikasÄ± ve amaÃ§larÄ±) izlenmektedir. Bu izleme sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek gÃ¼ncellemeler yapÄ±lmaktadÄ±r.","5":"Kurumda program Ã§Ä±ktÄ±larÄ±nÄ±n, kurumsal amaÃ§lar doÄŸrultusunda ve sÃ¼rdÃ¼rÃ¼lebilir ÅŸekilde izlenmesi gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun bu kapsamda kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no mechanism for monitoring and updating program outputs.","2":"Mechanisms (defined processes and performance indicators) for monitoring and updating program outcomes have been established. However, there is no application.","3":"Practices regarding monitoring program outcomes have been carried out in the