INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (40, 'C.1.1', 'Kurumun AraÅŸtÄ±rma PolitikasÄ±, Hedefleri ve Stratejisi', 'Research Policy, Goals and Strategy of the Institution', 'Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø« ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡ ÙˆØ¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØªÙ‡', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun tanÄ±mlÄ± araÅŸtÄ±rma politikasÄ±, stratejisi ve hedefleri bulunmamaktadÄ±r.","2":"Kurumun paydaÅŸlarÄ±yla oluÅŸturduÄŸu araÅŸtÄ±rmaya bakÄ±ÅŸ aÃ§Ä±sÄ±nÄ±, araÅŸtÄ±rma faaliyetlerinde izleyeceÄŸi ilkeleri, araÅŸtÄ±rmadaki Ã¶nceliklerini ve araÅŸ tÄ±rma kaynaklarÄ±nÄ± yÃ¶netmedeki tercihlerini ifade eden araÅŸtÄ±rma politikasÄ±, stratejisi ve hedefleri bulunmaktadÄ±r. Ancak bunlarÄ± hayata geÃ§irmek Ã¼zere mekanizmalar veya uygulamalar bulunmamaktadÄ±r.","3":"Kurumun tanÄ±mlÄ± araÅŸtÄ±rma politikasÄ±, stratejisi ve hed efleri doÄŸrultusunda yapÄ±lan uygulamalar bulunmaktadÄ±r. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± deÄŸerlendirilmemektedir.","4":"Kurumda tÃ¼m alanlar tarafÄ±ndan benimsenmiÅŸ araÅŸtÄ±rma politikasÄ±, stratejisi ve hedefleri ile ilgili uygulamalar, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek tÃ¼m alanlarÄ± kapsayan Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda araÅŸtÄ±rma alanÄ±ndaki faaliyetlerin, araÅŸtÄ±rma politikasÄ± doÄŸrultusunda deÄŸer Ã¼retebilmesi ve toplumsal faydaya dÃ¶nÃ¼ÅŸebilmesi gÃ¼vence altÄ±na alÄ±nm Ä±ÅŸ ve olgunlaÅŸmÄ±ÅŸ uygulamalarla paydaÅŸlarca benimsenmesi saÄŸlanmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have a defined research policy, strategy and objectives.","2":"The institution has a research policy, strategy and objectives that express its perspective on research with its stakeholders, the principles it will follow in its research activities, its priorities in research and its preferences in managing research resources. However, there are no mechanisms or practices to implement these.","3":"There are practices carried out in line with the defined research policy, strategy and objectives of the institution. However, the results of these applications are not evaluated.","4":"Practices related to the research policy, strategy and objectives adopted by all areas in the institution are systematically monitored and the monitoring results are evaluated together with stakeholders and measures are taken covering all areas.","5":"It is ensured that the activities in the field of research in the institution can produce value and turn into social benefit in line with the research policy, and that they are adopted by stakeholders with mature practices; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„ÙŠØ³ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø³ÙŠØ§Ø³Ø© Ø¨Ø­Ø«ÙŠØ© ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙˆØ£Ù‡Ø¯Ø§Ù Ù…Ø­Ø¯Ø¯Ø©.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø³ÙŠØ§Ø³Ø© ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙˆØ£Ù‡Ø¯Ø§Ù Ø¨Ø­Ø«ÙŠØ© ØªØ¹Ø¨Ø± Ø¹Ù† ÙˆØ¬Ù‡Ø© Ù†Ø¸Ø±Ù‡Ø§ Ø¨Ø´Ø£Ù† Ø§Ù„Ø¨Ø­Ø« Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©ØŒ ÙˆØ§Ù„Ù…Ø¨Ø§Ø¯Ø¦ Ø§Ù„ØªÙŠ Ø³ØªØªØ¨Ø¹Ù‡Ø§ ÙÙŠ Ø£Ù†Ø´Ø·ØªÙ‡Ø§ Ø§Ù„Ø¨Ø­Ø«ÙŠØ©ØŒ ÙˆØ£ÙˆÙ„ÙˆÙŠØ§ØªÙ‡Ø§ ÙÙŠ Ø§Ù„Ø¨Ø­Ø« ÙˆØªÙØ¶ÙŠÙ„Ø§ØªÙ‡Ø§ ÙÙŠ Ø¥Ø¯Ø§Ø±Ø© Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø­Ø«. Ù„ÙƒÙ† Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¢Ù„ÙŠØ§Øª Ø£Ùˆ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„ØªÙ†ÙÙŠØ°Ù‡Ø§.","3":"Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙŠØªÙ… ØªÙ†ÙÙŠØ°Ù‡Ø§ Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø³ÙŠØ§Ø³Ø© ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙˆØ£Ù‡Ø¯Ø§Ù Ø§Ù„Ø¨Ø­Ø« Ø§Ù„Ù…Ø­Ø¯Ø¯Ø© Ù„Ù„Ù…Ø¤Ø³Ø³Ø©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØªÙ‡ ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡ Ø§Ù„Ù…Ø