INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (41, 'C.1.2', 'AraÅŸtÄ±rma-GeliÅŸtirme SÃ¼reÃ§lerinin YÃ¶netimi ve Organizasyonel YapÄ±sÄ±', 'Management and Organizational Structure of Research and Development Processes', 'Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ±', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun araÅŸtÄ±rmageliÅŸtirme sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±sÄ±na iliÅŸkin bir planlama bulunmamaktadÄ±r.","2":"Kurumun araÅŸtÄ±rmageliÅŸtirme sÃ¼reÃ§lerinin yÃ¶netim ve organizasyonel yapÄ±sÄ±na iliÅŸkin planlamalar (karÄ±ÅŸmayan ile mÃ¼dahaleci spektrumun neresinde konumlandÄ±ÄŸÄ±, motivasyon ve yÃ¶nlendirme iÅŸlevinin nasÄ±l tasarlandÄ±ÄŸÄ±, kÄ±sa ve uzun vadeli hedeflerin net ve kesin nasÄ±l tanÄ±mlandÄ±ÄŸÄ±, araÅŸtÄ±rma yÃ¶netimi ekibi ve gÃ¶rev tanÄ±mlarÄ±) bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamayan uygulamalar bulunmaktadÄ±r.","3":"Kurumunda tÃ¼m alanlarÄ± kapsayÄ±cÄ± ÅŸekilde araÅŸtÄ±rmageliÅŸtirme sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±sÄ± kurumsal tercihler yÃ¶nÃ¼nde uygulamaya konularak bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§lar izlenmemektedir.","4":"Kurumda araÅŸtÄ±rmageliÅŸtirme sÃ¼reÃ§lerinin yÃ¶netimi ile iliÅŸkili sonuÃ§lar ve paydaÅŸ gÃ¶rÃ¼ÅŸleri sistematik olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda tÃ¼m alanlarÄ± kapsayan araÅŸtÄ±rma-geliÅŸtirme yÃ¶netimi, kurumsal amaÃ§lar (araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda bÃ¼tÃ¼nleÅŸtirici, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no plan regarding the management and organizational structure of the institution''s research and development processes.","2":"There are plans regarding the management and organizational structure of the institution''s research and development processes (where it is located on the non-interventionist and interventionist spectrum, how the motivation and guidance function is designed, how short and long-term goals are clearly and precisely defined, the research management team and job descriptions). However, there are no applications made in line with these plans, or there are applications that do not cover all areas.","3":"Some results have been achieved by implementing the management and organizational structure of research and development processes in the institution, covering all areas, in line with institutional preferences. However, these results are not monitored.","4":"The results and stakeholder opinions related to the management of research and development processes in the institution are systematically monitored and measures are taken by evaluating them together with the stakeholders.","5":"Research and development management, covering all areas in the institution, has been adopted and secured throughout the institution with integrative, sustainable and mature practices in line with institutional goals (research policy, objectives, strategy); The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø®Ø·Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¥Ø¯Ø§Ø±ÙŠ ÙˆØ§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· ØªØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© (Ø­ÙŠØ« ØªÙ‚Ø¹ Ø¹Ù„Ù