ut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (42, 'C.1.3', 'AraÅŸtÄ±rmalarÄ±n Yerel/BÃ¶lgesel/Ulusal Ä°htiyaÃ§ ve Taleplerle Ä°liÅŸkisi', 'Relationship of Research to Local/Regional/National Needs and Demands', 'Ø¹Ù„Ø§Ù‚Ø© Ø§Ù„Ø¨Ø­Ø« Ø¨Ø§Ù„Ø§Ø­ØªÙŠØ§Ø¬Ø§Øª ÙˆØ§Ù„Ø·Ù„Ø¨Ø§Øª Ø§Ù„Ù…Ø­Ù„ÙŠØ©/Ø§Ù„Ø¥Ù‚Ù„ÙŠÙ…ÙŠØ©/Ø§Ù„ÙˆØ·Ù†ÙŠØ©', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurum araÅŸtÄ±rmalarÄ±n planlamasÄ±, yÃ¼rÃ¼tÃ¼lmesi veya yÃ¶netilmesinde yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§, talep ve deÄŸiÅŸimleri dikkate almamaktadÄ±r.","2":"Kurum, araÅŸtÄ±rmalarÄ±n planlamasÄ±nda, yÃ¼rÃ¼tÃ¼lmesinde veya yÃ¶netilmesinde yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§, talep ve deÄŸiÅŸimleri dikkate almaktadÄ±r. Ancak bu uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r veya kurumun araÅŸtÄ±rma politikasÄ±, hedefleri ve stratejisine yansÄ±tÄ±lmamaktadÄ±r.","3":"Kurum araÅŸtÄ±rma ile iliÅŸkili tÃ¼m alanlardaki araÅŸtÄ±rmalarÄ±n planlamasÄ±nda, yÃ¼rÃ¼tÃ¼lmesinde veya yÃ¶netilmesinde yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§, talep ve deÄŸiÅŸimleri dikkate almaktadÄ±r. Ancak bu uygulamalarla ilgili sonuÃ§lar izlenmemektedir.","4":"Kurumda araÅŸtÄ±rma sonuÃ§lar; yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§ ve taleplerle iliÅŸkili olarak sistematik ve kurumun iÃ§ kalite gÃ¼vencesi sistemiyle uyumlu olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlem alÄ±nmaktadÄ±r.","5":"Kurumda araÅŸtÄ±rmalarÄ±n; yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§ ve taleplere dini sosyokÃ¼ltÃ¼rel katkÄ±sÄ± ile (ulusal/uluslararasÄ±) deÄŸerlendirilmesi kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun bu hususta kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not take into account local, regional and national needs, demands and changes in the planning, conduct or management of research.","2":"The institution takes into account local, regional and national needs, demands and changes in the planning, conduct or management of research. However, these practices do not cover all areas or are not reflected in the institution''s research policy, objectives and strategy.","3":"The institution takes into account local, regional and national needs, demands and changes in the planning, conduct or management of research in all research-related fields. However, the results of these practices are not monitored.","4":"Research results in the institution; It is monitored systematically and in accordance with the institution''s internal quality assurance system in relation to local, regional and national needs and demands, and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"Research in the institution; The evaluation of local, regional and national needs and demands with their religious socio-cultural contribution (national/international) is adopted and guaranteed throughout the institution; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªØ£Ø®Ø° Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠ Ø§Ù„Ø§Ø¹ØªØ¨Ø§Ø± Ø§Ù„Ø§Ø­ØªÙŠØ§Ø¬Ø§Øª ÙˆØ§Ù„Ù…ØªØ·Ù„Ø¨Ø§Øª ÙˆØ§Ù„ØªØºÙŠØ±Ø§Øª Ø§Ù„Ù…Ø­Ù„ÙŠØ© ÙˆØ§Ù„Ø¥Ù‚Ù„ÙŠÙ…ÙŠØ© ÙˆØ§Ù„ÙˆØ·Ù†ÙŠØ© ÙÙŠ ØªØ®Ø·ÙŠØ· Ø£Ùˆ Ø¥Ø¬Ø±Ø§Ø¡ Ø£Ùˆ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¨Ø­ÙˆØ«.","2":"ØªØ£Ø®Ø° Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠ Ø§Ù„Ø§Ø¹ØªØ¨Ø§Ø± Ø§Ù„Ø§Ø­ØªÙŠØ§Ø¬Ø§Øª ÙˆØ§Ù„Ù…ØªØ·Ù„Ø¨Ø§Øª ÙˆØ§Ù„ØªØºÙŠØ±Ø§Øª Ø§Ù„Ù…Ø­Ù„ÙŠØ© ÙˆØ§Ù„Ø¥Ù‚Ù„ÙŠÙ…ÙŠØ© ÙˆØ§Ù„ÙˆØ·Ù†ÙŠØ© ÙÙŠ ØªØ®Ø·ÙŠØ· Ø£Ùˆ Ø¥Ø¬Ø±Ø§Ø¡ Ø£Ùˆ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¨Ø­ÙˆØ«. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ ÙØ¥Ù† Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª Ø£Ùˆ Ù„Ø§ ØªÙ†Ø¹ÙƒØ³ ÙÙŠ Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø« ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡ ÙˆØ§Ø³Ø