INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (45, 'C.2.3', 'Ãœniversite DÄ±ÅŸÄ± Kaynaklara YÃ¶nelik YÃ¶ntem ve Destekler', 'Methods and Support for Non-University Resources', 'Ø·Ø±Ù‚ ÙˆØ¯Ø¹Ù… Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ ØºÙŠØ± Ø§Ù„Ø¬Ø§Ù…Ø¹ÙŠØ©', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun araÅŸtÄ±rma ve geliÅŸtirme faaliyetleri iÃ§in Ã¼niversite dÄ±ÅŸÄ± kaynaklara herhangi bir yÃ¶nelimi bulunmamaktadÄ±r.","2":"Kurumun Ã¼niversite dÄ±ÅŸÄ± kaynaklarÄ± oluÅŸturmak iÃ§in planlarÄ± ve bu kaynaklarÄ±n kullanÄ±mÄ±na iliÅŸkin yÃ¶ntem ve destek sÃ¼reÃ§leri bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumun araÅŸtÄ±rma ve geliÅŸtirme faaliyetlerini kurumsal amaÃ§lar doÄŸrultusunda sÃ¼rdÃ¼rebilmek iÃ§in Ã¼niversite dÄ±ÅŸÄ± kaynaklarÄ±n kullanÄ±mÄ±na yÃ¶nelik yÃ¶ntem ve destek planlarÄ± oluÅŸturulmuÅŸ ve tÃ¼m alanlarÄ± kapsayan uygulamalar bulunmaktadÄ±r. Ancak bu kaynaklarÄ±n kullanÄ±mÄ±na ve uygulamalara yÃ¶nelik sonuÃ§lar izlenmemektedir.","4":"Kurumda, araÅŸtÄ±rma ve geliÅŸtirme faaliyetlerini kurumsal amaÃ§lar doÄŸrultusunda sÃ¼rdÃ¼rebilmek iÃ§in Ã¼niversite dÄ±ÅŸÄ± kaynaklarÄ±n kullanÄ±mÄ±nÄ± destekleyen uygulamalardan elde edilen bulgular, sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, araÅŸtÄ±rma ve geliÅŸtirme faaliyetlerini kurumsal amaÃ§lar (araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda sÃ¼rdÃ¼rebilmek iÃ§in Ã¼niversite dÄ±ÅŸÄ± kaynaklarÄ±n kullanÄ±mÄ±na iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have any orientation towards non-university resources for its research and development activities.","2":"The institution has plans to create non-university resources and methods and support processes for the use of these resources. However, there are no applications made in line with these plans or they do not cover all areas.","3":"In order to continue the research and development activities of the institution in line with corporate goals, method and support plans have been created for the use of non-university resources and there are practices covering all areas. However, the results regarding the use of these resources and practices are not monitored.","4":"In order to continue research and development activities in line with institutional goals, the findings obtained from practices that support the use of non-university resources are systematically monitored and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In order to continue research and development activities in line with institutional goals (research policy, goals, strategy), sustainable and mature practices regarding the use of non-university resources have been adopted and secured throughout the institution; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„ÙŠØ³ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø£ÙŠ ØªÙˆØ¬Ù‡ Ù†Ø­Ùˆ Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ ØºÙŠØ± Ø§Ù„Ø¬Ø§Ù…Ø¹ÙŠØ© Ù„Ø£Ù†Ø´Ø·ØªÙ‡Ø§ Ø§Ù„Ø¨Ø­Ø«ÙŠØ© ÙˆØ§Ù„ØªØ·ÙˆÙŠØ±ÙŠØ©.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø®Ø·Ø· Ù„Ø¥Ù†Ø´Ø§Ø¡ Ù…ÙˆØ§Ø±Ø¯ ÙˆØ£Ø³Ø§Ù„ÙŠØ¨ ØºÙŠØ± Ø¬Ø§Ù…Ø¹ÙŠØ© ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ø¯Ø¹Ù… Ù„Ø§Ø³ØªØ®Ø¯Ø§Ù… Ù‡Ø°Ù‡ Ø§Ù„Ù…ÙˆØ§Ø±Ø¯. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ø·Ù„Ø¨Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø· Ø£Ùˆ Ø£Ù†Ù‡Ø§ Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"Ù…Ù† Ø£Ø¬Ù„ Ù…ÙˆØ§ØµÙ„Ø© Ø£Ù†Ø´Ø·Ø© Ø§Ù„Ø¨Ø­Ø« ÙˆØ§