INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (46, 'C.2.4', 'Kurumun AraÅŸtÄ±rma PolitikasÄ± ve Uyumlu LisansÃ¼stÃ¼ Programlar', 'Institution''s Research Policy and Compatible Graduate Programs', 'Ø§Ù„Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆØ¨Ø±Ø§Ù…Ø¬ Ø§Ù„Ø¯Ø±Ø§Ø³Ø§Øª Ø§Ù„Ø¹Ù„ÙŠØ§ Ø§Ù„Ù…ØªÙˆØ§ÙÙ‚Ø©', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi ile uyumlu lisansÃ¼stÃ¼ programlar bulunmamaktadÄ±r.","2":"Kurumun araÅŸtÄ±rma politikasÄ±, hedefleri ve stratejileri ile uyumlu lisansÃ¼stÃ¼ programlara iliÅŸkin planlar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu planlar ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumda araÅŸtÄ±rma politikasÄ±, hedefleri ve stratejiler i ile uyumlu ve destekleyen lisansÃ¼stÃ¼ programlar yÃ¼rÃ¼tÃ¼lmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumda araÅŸtÄ±rma politikasÄ±, hedefleri ve stratejileri ile uyumlu ve destekleyen lisansÃ¼stÃ¼ programlarÄ±n Ã§Ä±ktÄ±larÄ± dÃ¼zenli olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, araÅŸtÄ±rma ve geliÅŸtirme faaliyetlerini kurumsal amaÃ§lar (araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda sÃ¼rdÃ¼rebilmek iÃ§in lisansÃ¼stÃ¼ programlara iliÅŸkin bÃ¼tÃ¼nleÅŸik ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no graduate programs compatible with the institution''s research policy, goals and strategy.","2":"There are plans and defined processes for graduate programs that are compatible with the institution''s research policy, goals and strategies. However, there are no practices made in line with these plans and processes or they do not cover all areas.","3":"The institution carries out postgraduate programs that are compatible with and support the research policy, goals and strategies. However, the results of these practices are not monitored.","4":"The outputs of graduate programs that are compatible with and support the institution''s research policy, goals and strategies are regularly monitored, and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In order to continue research and development activities in line with institutional goals (research policy, objectives, strategy), integrated and mature practices regarding postgraduate programs have been adopted and secured throughout the institution; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¨Ø±Ø§Ù…Ø¬ Ø¯Ø±Ø§Ø³Ø§Øª Ø¹Ù„ÙŠØ§ Ù…ØªÙˆØ§ÙÙ‚Ø© Ù…Ø¹ Ø§Ù„Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡Ø§ ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØªÙ‡Ø§.","2":"Ù‡Ù†Ø§Ùƒ Ø®Ø·Ø· ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø¨Ø±Ø§Ù…Ø¬ Ø§Ù„Ø¯Ø±Ø§Ø³Ø§Øª Ø§Ù„Ø¹Ù„ÙŠØ§ ØªØªÙˆØ§ÙÙ‚ Ù…Ø¹ Ø§Ù„Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡Ø§ ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ§ØªÙ‡Ø§. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø· ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø£Ùˆ Ø£Ù†Ù‡Ø§ Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ØªÙ†ÙØ° Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø±Ø§Ù…Ø¬ Ø§Ù„Ø¯Ø±Ø§Ø³Ø§Øª Ø§Ù„Ø¹Ù„ÙŠØ§ Ø§Ù„ØªÙŠ ØªØªÙˆØ§ÙÙ‚ Ù…Ø¹ ÙˆØªØ¯Ø¹Ù… Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø« ÙˆØ£Ù‡Ø¯Ø§ÙÙ‡ ÙˆØ§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ§ØªÙ‡. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø®Ø±Ø¬Ø§Øª Ø¨Ø±Ø§Ù…Ø¬ Ø§Ù„Ø¯Ø±Ø§Ø³Ø§Øª Ø§Ù„Ø¹Ù„ÙŠØ§ Ø§Ù„Ù…ØªÙˆØ§ÙÙ‚Ø© Ù…Ø¹ Ø§Ù„Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ø¨Ø­Ø«Ù