INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (47, 'C.3.1', 'Ã–ÄŸretim ElemanlarÄ±nÄ±n AraÅŸtÄ±rma YetkinliÄŸinin GeliÅŸtirilmesi', 'Improving the Research Competency of Faculty Members', 'ØªØ­Ø³ÙŠÙ† Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda, Ã¶ÄŸretim elemanlarÄ±nÄ±n araÅŸtÄ±rma yetkinliÄŸinin (uzmanlÄ±klar, birikim, sayÄ± ve daÄŸÄ±lÄ±m) deÄŸerlendirilmesine ve geliÅŸtirilmesine yÃ¶nelik bir mekanizma bulunmamaktadÄ±r.","2":"Kurumda, Ã¶ÄŸretim elemanlarÄ±nÄ±n araÅŸtÄ±rma yetkinliÄŸinin deÄŸerlendirilmesine ve geliÅŸtirilmesine yÃ¶nelik planlar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu planlar ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamayan uygulamalar bulunm aktadÄ±r.","3":"Kurumda, Ã¶ÄŸretim elemanlarÄ±nÄ±n araÅŸtÄ±rma yetkinliÄŸinin deÄŸerlendirilmesine ve geliÅŸtirilmesine yÃ¶nelik uygulamalar tÃ¼m alanlarÄ± kapsayan ÅŸekilde yÃ¼rÃ¼tÃ¼lmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumda, Ã¶ÄŸretim elemanlarÄ±nÄ±n araÅŸtÄ±rma yetkinliÄŸinin deÄŸerlendirilmesine ve geliÅŸtirilmesine yÃ¶nelik uygulamalar dÃ¼zenli olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, kurumsal amaÃ§lar (araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda Ã¶ÄŸretim elemanlarÄ±nÄ±n araÅŸtÄ±rma yetkinliÄŸinin deÄŸerlendirilmesi ve geliÅŸtirilmesine iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygu lamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have a mechanism for evaluating and developing the research competence of faculty members (specialties, background, number and distribution).","2":"The institution has plans and defined processes for evaluating and developing the research competence of faculty members. However, there are no practices made in line with these plans and processes, or there are practices that do not cover all areas.","3":"In the institution, practices aimed at evaluating and developing the research competence of faculty members are carried out in a way that covers all areas. However, the results of these practices are not monitored.","4":"In the institution, practices aimed at evaluating and developing the research competence of faculty members are regularly monitored, and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In the institution, sustainable and mature practices regarding the evaluation and development of faculty members'' research competence in line with institutional goals (research policy, goals, strategy) have been adopted and secured throughout the institution; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¢Ù„ÙŠØ© Ù„ØªÙ‚ÙŠÙŠÙ… ÙˆØªØ·ÙˆÙŠØ± Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³ (Ø§Ù„ØªØ®ØµØµØ§Øª ÙˆØ§Ù„Ø®Ù„ÙÙŠØ© ÙˆØ§Ù„Ø¹Ø¯Ø¯ ÙˆØ§Ù„ØªÙˆØ²ÙŠØ¹).","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø®Ø·Ø· ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„ØªÙ‚ÙŠÙŠÙ… ÙˆØªØ·ÙˆÙŠØ± Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ© Ù„Ø£Ø¹Ø¶Ø§Ø¡ Ù‡ÙŠØ¦Ø© Ø§Ù„ØªØ¯Ø±ÙŠØ³. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø· ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§ØªØŒ Ø£Ùˆ Ø£Ù† Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙŠØªÙ… ØªÙ†ÙÙŠØ° Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ØªÙŠ ØªÙ‡Ø¯Ù Ø¥Ù„Ù‰ ØªÙ‚ÙŠÙŠÙ… ÙˆØªØ·ÙˆÙŠØ± Ø§Ù„ÙƒÙØ§Ø¡Ø© Ø§Ù„Ø¨Ø­Ø«ÙŠØ