INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (48, 'C.3.2', 'Ulusal ve UluslararasÄ± AraÅŸtÄ±rma Birimleri ile Ortak Programlar', 'Joint Programs with National and International Research Units', 'Ø¨Ø±Ø§Ù…Ø¬ Ù…Ø´ØªØ±ÙƒØ© Ù…Ø¹ ÙˆØ­Ø¯Ø§Øª Ø§Ù„Ø¨Ø­ÙˆØ« Ø§Ù„ÙˆØ·Ù†ÙŠØ© ÙˆØ§Ù„Ø¯ÙˆÙ„ÙŠØ©', 3, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda ulusal ve uluslararasÄ± dÃ¼zeyde kurum iÃ§i ve kurumlar arasÄ± ortak programlar ve ortak araÅŸtÄ±rma birimleri ile araÅŸtÄ±rma aÄŸlarÄ±na katÄ±lÄ±m ve iÅŸbirlikleri kurma gibi Ã§oklu araÅŸtÄ±rma faaliyetleri bulunmamaktadÄ±r.","2":"Kurumda ulusal ve uluslararasÄ± dÃ¼zeyde kurum iÃ§i ve kurumlar arasÄ± ortak programlar ve ortak araÅŸtÄ±rma birimleri ile ara ÅŸtÄ±rma aÄŸlarÄ±na katÄ±lÄ±m ve iÅŸbirlikleri kurma gibi Ã§oklu araÅŸtÄ±rma faaliyetlerine yÃ¶nelik planlamalar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu planlar ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r.","3":"Kurumda ulusal ve uluslararasÄ± dÃ¼zeyde kurum iÃ§i ve kurumlar arasÄ± ortak programlar ve ortak araÅŸtÄ±rma birimleri ile araÅŸtÄ±rma aÄŸlarÄ±na katÄ±lÄ±m ve iÅŸbirlikleri kurma gibi Ã§oklu araÅŸtÄ±rma faaliyetleri ve uygulamalar tÃ¼m alanlarda yÃ¼rÃ¼tÃ¼lmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir.","4":"Kurumda ulusal ve uluslararasÄ± dÃ¼zeyde kurum iÃ§i ve kurumlar arasÄ± ortak programlar ve ortak araÅŸtÄ±rma birimleri ile araÅŸtÄ±rma aÄŸlarÄ±na katÄ±lÄ±m ve iÅŸbirlikleri kurma gibi Ã§oklu araÅŸtÄ±rma faaliyetleri ve uygulamalar dÃ¼zenli olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, kurumsal amaÃ§lar (araÅŸtÄ±rma politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda kurum iÃ§i ve kurumlar arasÄ±, ulusal ve uluslararasÄ± dÃ¼zeyde ortak programlar ve ortak araÅŸtÄ±rma birim leri, iÅŸbirlikleri ve araÅŸtÄ±rma aÄŸlarÄ±na katÄ±lÄ±m gibi Ã§oklu araÅŸtÄ±rma faaliyetlerine ve uygulamalarÄ±na iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uy gulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have multiple research activities such as intra-institutional and inter-institutional joint programs and joint research units at national and international levels, as well as participation in research networks and establishing collaborations.","2":"The institution has plans and defined processes for multiple research activities such as intra-institutional and inter-institutional joint programs and participation in research networks with joint research units and establishing collaborations at national and international levels. However, there are no practices made in line with these plans and processes.","3":"Multiple research activities and practices are carried out in all areas of the institution, such as participating in research networks and establishing collaborations with intra-institutional and inter-institutional joint programs and joint research units at national and international levels. However, the results of these practices are not monitored.","4":"Multiple research activities and practices, such as participation in research networks and establishing collaborations with intra-institutional and inter-institutional joint programs and joint research units at national and international levels, are regularly monitored in the institution, and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In the institution, sustainable and mature practices regarding multiple research activities and practices, such as joint programs and joint research un