INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (53, 'D.1.2', 'Toplumsal KatkÄ± SÃ¼reÃ§lerinin YÃ¶netimi ve TeÅŸkilat YapÄ±sÄ±', 'Management and Organizational Structure of Social Contribution Processes', 'Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©', 4, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun toplumsal katkÄ± sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±sÄ±na iliÅŸkin bir planlamasÄ± bulunmamaktadÄ±r.","2":"Kurumun toplumsal katkÄ± sÃ¼reÃ§lerinin, yerel, bÃ¶lgesel ve ulusal ihtiyaÃ§ ve talepler ile iliÅŸkili ve diÄŸer sÃ¼reÃ§lerle (eÄŸitimÃ¶ÄŸretim, araÅŸtÄ±rma-geliÅŸtirme) bÃ¼tÃ¼nleÅŸik olarak yÃ¶netimi ve organizasyonel yapÄ±lanmasÄ± (sÃ¼reÃ§ler ve gÃ¶rev tanÄ±mlarÄ± vb.) yÃ¶nelik planlar bulunmaktadÄ±r. Ancak bu planlar doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamayan uygulamalar bulunmaktadÄ±r.","3":"FakÃ¼ltede toplumsal katkÄ± sÃ¼reÃ§lerinin yÃ¶netimi ve organizasyonel yapÄ±lanmasÄ± kurumsal tercihler yÃ¶nÃ¼nde ve tÃ¼m alanlarÄ± kapsayÄ±cÄ± ÅŸekilde uygulamaya konularak bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§lar izlenmemektedir.","4":"Kurumda toplumsal katkÄ± sÃ¼reÃ§lerinin yÃ¶netimi ile iliÅŸkili sonuÃ§lar ve paydaÅŸ gÃ¶rÃ¼ÅŸleri sistematik ve kurumun iÃ§ kalite gÃ¼vence sistemiyle uyumlu olarak izlenmekte ve paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlem alÄ±nmaktadÄ±r.","5":"Kurumda tÃ¼m alanlarÄ± kapsayan toplumsal katkÄ± sÃ¼reÃ§lerinin yÃ¶netimi kurumsal amaÃ§lar doÄŸrultusunda bÃ¼tÃ¼nleÅŸtirici, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have a plan regarding the management and organizational structure of social contribution processes.","2":"There are plans for the management and organizational structuring (processes and job descriptions, etc.) of the institution''s social contribution processes in relation to local, regional and national needs and demands and integrated with other processes (education, research and development). However, there are no applications made in line with these plans, or there are applications that do not cover all areas.","3":"Some results have been achieved by implementing the management and organizational structuring of social contribution processes at the faculty in line with institutional preferences and in a way that covers all areas. However, these results are not monitored.","4":"The results and stakeholder opinions related to the management of social contribution processes in the institution are monitored systematically and in accordance with the internal quality assurance system of the institution, and measures are taken by evaluating them together with the stakeholders.","5":"The management of social contribution processes covering all areas in the institution has been adopted and secured throughout the institution with integrative, sustainable and mature practices in line with corporate goals; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„ÙŠØ³ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø®Ø·Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©.","2":"ØªÙˆØ¬Ø¯ Ø®Ø·Ø· Ù„Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„ØªÙ†Ø¸ÙŠÙ…ÙŠ (Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª ÙˆØ§Ù„ØªÙˆØµÙŠÙ Ø§Ù„ÙˆØ¸ÙŠÙÙŠØŒ ÙˆÙ…Ø§ Ø¥Ù„Ù‰ Ø°Ù„Ùƒ) Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø§Ù„Ø§Ø­ØªÙŠØ§Ø¬Ø§Øª ÙˆØ§Ù„Ù…ØªØ·Ù„Ø¨Ø§Ø