INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (55, 'D.3', 'Toplumsal KatkÄ± PerformansÄ±', 'Social Contribution Performance', 'Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©', 4, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda toplumsal katkÄ± performansÄ±nÄ±n izlenmesine ve iyileÅŸtirilmesine yÃ¶nelik uygulamalar bulunmamaktadÄ±r.","2":"Kurumda toplumsal katkÄ± performansÄ±nÄ±n izlenmesine ve iyileÅŸtirilmesine yÃ¶nelik planlamalar ve tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu planlar ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya tÃ¼m alanlarÄ± kapsamayan uygulamalar bulunmaktadÄ±r.","3":"Kurumda toplumsal katkÄ± performansÄ±nÄ±n izlenmesine ve iyileÅŸtirilmesine yÃ¶nelik uygulamalar tÃ¼m alanlarÄ± kapsar ÅŸekilde yÃ¼rÃ¼tÃ¼lmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemektedir veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda tÃ¼m alanlarÄ±n toplumsal katkÄ± performansÄ± izlenerek deÄŸerlendirilmekte ve karar almalarda kullanÄ±lmaktadÄ±r. Buna iliÅŸkin uygulamalar dÃ¼zenli olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda, kurumsal amaÃ§lar (toplumsal katkÄ± politikasÄ±, hedefleri, stratejisi) doÄŸrultusunda tÃ¼m alanlarÄ±n toplumsal katkÄ± performansÄ±nÄ±n izlenmesi ve deÄŸerlendirilmesine iliÅŸkin sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalar kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no practices in the institution to monitor and improve social contribution performance.","2":"The institution has plans and defined processes for monitoring and improving social contribution performance. However, there are no applications made in line with these plans and processes, or there are applications that do not cover all areas.","3":"Practices aimed at monitoring and improving social contribution performance in the institution are carried out in a way that covers all areas. However, the results of these applications are not monitored or used in decision-making.","4":"The social contribution performance of all areas in the institution is monitored and evaluated and used in decision-making. Related practices are monitored regularly and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"In the institution, sustainable and mature practices regarding monitoring and evaluating the social contribution performance of all areas in line with corporate objectives (social contribution policy, goals, strategy) have been adopted and secured throughout the institution; The institution has many unique and innovative applications, and some of these applications are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªØ­Ø³ÙŠÙ† Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø®Ø·Ø· ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø±ØµØ¯ ÙˆØªØ­Ø³ÙŠÙ† Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ø·Ù„Ø¨Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø·Ø· ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§ØªØŒ Ø£Ùˆ Ù‡Ù†Ø§Ùƒ Ø·Ù„Ø¨Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ÙŠØªÙ… ØªÙ†ÙÙŠØ° Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ØªÙŠ ØªÙ‡Ø¯Ù Ø¥Ù„Ù‰ Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªØ­Ø³ÙŠÙ† Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø·Ø±ÙŠÙ‚Ø© ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ÙŠØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© ÙˆØªÙ‚ÙŠÙŠÙ… Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© Ù„Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆØ§Ø³ØªØ®Ø¯Ø§Ù…Ù‡ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±. ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø°Ø§Øª Ø§Ù„ØµÙ„Ø© Ø¨Ø§Ù†ØªØ¸Ø§Ù… ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ ÙˆØªØ£Ù…ÙŠÙ† Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø±ØµØ¯ ÙˆØªÙ‚ÙŠÙŠÙ… Ø£Ø¯Ø§Ø¡ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ø´Ø±ÙƒØ© (Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ©ØŒ ÙˆØ§Ù„Ø£Ù‡Ø¯Ø§ÙØŒ ÙˆØ§Ù„Ø§Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ©) ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø› ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ø¹Ø¯ÙŠØ¯ Ù…Ù† Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø§Ù„ÙØ±ÙŠØ¯Ø© ÙˆØ§Ù„Ù…Ø¨ØªÙƒØ±Ø©ØŒ ÙˆØ¨Ø¹Ø¶ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª ØªØªØ®Ø° Ù…Ø«Ø§Ù„Ø§Ù‹ Ù…Ù† Ù‚Ø¨Ù„ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aciklama_metni":"","aciklama_metni_en":"","uygulama_alanlari":"","ilk_planlama_tarihi":"","izleme_mekanizmalari":"","uluslararasi_paydaslar":"","performans_gostergeleri":"","degerlendirme_iyilestirme_tarihi":""}'::jsonb) ON CONFLICT (id) DO UPDATE SET olcut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (56, 'E.1.1', 'YÃ¶netim Modeli ve Ä°dari YapÄ±', 'Management Model and Administrative Structure', 'Ù†Ù…ÙˆØ°Ø¬ Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙˆØ§Ù„Ù‡ÙŠÙƒÙ„ Ø§Ù„Ø¥Ø¯Ø§Ø±ÙŠ', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun misyonuyla uyumlu ve stratejik hedeflerini gerÃ§ekleÅŸtirmeyi saÄŸlayacak bir yÃ¶netim modeli ve organizasyonel yapÄ±lanmasÄ± bulunmamaktadÄ±r.","2":"Kurumun misyon ve stratejik hedeflerine ulaÅŸmasÄ±nÄ± gÃ¼vence altÄ±na alan yÃ¶netim modeli ve idari yapÄ±lanmasÄ±; tÃ¼m sÃ¼reÃ§ler tanÄ±mlanarak, sÃ¼reÃ§lerle uyumlu yetki, gÃ¶rev ve sorumluluklar belirlenerek tanÄ±mlanmÄ±ÅŸtÄ±r. Ancak bu model doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya uygulamalar tÃ¼m birimleri kapsamamaktadÄ±r.","3":"Kurumun misyon ve stratejik hedeflerine ulaÅŸmasÄ±nÄ± gÃ¼vence altÄ±na alan yÃ¶netim modeli ve idari yapÄ±lanmasÄ±, sÃ¼reÃ§lerle uyumlu olarak ve tÃ¼m birimleri/alanlarÄ± kapsayacak ÅŸekilde oluÅŸturulmuÅŸtur ve bu doÄŸrultuda yapÄ±lan uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu sonuÃ§larÄ±n izlenmesi yapÄ±lmamaktadÄ±r.","4":"Kurumda tÃ¼m birimleri ve alanlarÄ± kapsayan yÃ¶netim modeli ve idari yapÄ±lanmasÄ± ile iliÅŸkili uygulamalardan elde edilen bulgular, sistematik olarak izlenmekte, paydaÅŸlarÄ±n gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmakta ve ihtiyaÃ§lar/talepler doÄŸrultusunda gÃ¼ncellemeler gerÃ§ekleÅŸtirilmektedir.","5":"Kurumda Ã§ok sesliliÄŸi, etkin karar vermeyi, deÄŸiÅŸime uyum saÄŸlamayÄ± ve paydaÅŸlarÄ±n temsil edilmesini gÃ¼vence altÄ±na alan ve kurumsal amaÃ§larÄ±n gerÃ§ekleÅŸtirilmesi iÃ§in gerekli ortamÄ± saÄŸlayan yÃ¶netim modeli ve idari yapÄ±lanmasÄ± (yasal dÃ¼zenlemeler Ã§erÃ§evesinde kurumsal yaklaÅŸÄ±m, gelenekler, tercihler) kurumun tamamÄ±nda benimsenmiÅŸtir; kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have a management model and organizational structure that is compatible with its mission and will enable it to achieve its strategic goals.","2":"The management model and administrative structure that ensures that the institution achieves its mission and strategic goals; All processes are defined and the authorities, duties and responsibilities compatible with the processes are determined. However, there are no applications made in line with this model or the applications do not cover all units.","3":"The management model and administrative structuring that ensures that the institution achieves its mission and strategic goals has been created in accordance with the processes and covering all units/areas, and some results have been obtained from the practices carried out in this direction. However, these results are not monitored.","4":"The findings obtained from the practices related to the management model and administrative structure covering all units and areas in the institution are systematically monitored, the opinions of the stakeholders are taken and the monitoring results are evaluated together with the stakeholders, measures are taken and updates are made in line with the needs/demands.","5":"The management model and administrative structuring (institutional approach, traditions, preferences within the framework of legal regulations) that ensures polyphony, effective decision-making, adaptation to change and representation of stakeholders in the institution and provides the necessary environment for the realization of corporate goals are adopted throughout the institution; The institution has many unique and innovative applications, and some of these applications are taken as an example by othe