INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (57, 'E.1.2', 'SÃ¼reÃ§ YÃ¶netimi', 'Process Management', 'Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda eÄŸitim Ã¶ÄŸretim, araÅŸtÄ±rma geliÅŸtirme, toplumsal katkÄ± ve yÃ¶netim sistemine iliÅŸkin sÃ¼reÃ§ler tanÄ±mlanmamÄ±ÅŸtÄ±r.","2":"Kurumda eÄŸitim Ã¶ÄŸretim, araÅŸtÄ±rmageliÅŸtirme, toplumsal katkÄ± ve yÃ¶netim sistemine iliÅŸkin sÃ¼reÃ§ler tanÄ±mlanmÄ±ÅŸtÄ±r. Ancak uygulamalar bu sÃ¼reÃ§lerle uyumlu deÄŸildir veya tÃ¼m birimleri kapsamayan uygulamalar bulunmaktadÄ±r.","3":"Kurumda tÃ¼m birimleri ve alanlarÄ± kapsayacak ÅŸekilde tÃ¼m sÃ¼reÃ§ler tanÄ±mlanmÄ±ÅŸtÄ±r ve tÃ¼m uygulamalar sÃ¼reÃ§ler doÄŸrultusunda gerÃ§ekleÅŸtirilmektedir. Ancak sÃ¼reÃ§ perf ormans sonuÃ§larÄ± izlenmemekte veya sÃ¼reÃ§ performans sonuÃ§larÄ± karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda tÃ¼m birimleri ve alanlarÄ± kapsayacak ÅŸekilde yÃ¶netilen sÃ¼reÃ§lere iliÅŸkin sonuÃ§lar, performans gÃ¶stergeleriyle sistematik olarak izlenmekte, paydaÅŸlarÄ± n gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmakta ve ihtiyaÃ§lar/talepler doÄŸrultusunda gÃ¼ncellemeler gerÃ§ekleÅŸtirilmektedir.","5":"Kurumda stratejik hedeflerle uyumlu ve tÃ¼m alanlarÄ± kapsayan sÃ¼reÃ§ yÃ¶netim modeli sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The processes related to education, research and development, social contribution and management system are not defined in the institution.","2":"Processes regarding education and training, research and development, social contribution and management system have been defined in the institution. However, applications are not compatible with these processes or there are applications that do not cover all units.","3":"All processes have been defined to cover all units and areas in the institution and all applications are carried out in line with the processes. However, process performance results are not monitored or process performance results are not used in decision making.","4":"The results of the processes managed to cover all units and areas in the institution are systematically monitored with performance indicators, the opinions of the stakeholders are taken and the monitoring results are evaluated together with the stakeholders, measures are taken and updates are made in line with the needs/demands.","5":"The process management model, which is compatible with strategic goals and covers all areas in the institution, has been adopted and secured throughout the institution with sustainable and mature practices; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ù… ÙŠØªÙ… ØªØ¹Ø±ÙŠÙ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙˆØ§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙˆÙ†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"ØªÙ… ØªØ­Ø¯ÙŠØ¯ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ ÙˆØ§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙˆØ§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙˆÙ†Ø¸Ø§Ù… Ø§Ù„Ø¥Ø¯Ø§Ø±Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©. Ø¥Ù„Ø§ Ø£Ù† Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª ØºÙŠØ± Ù…ØªÙˆØ§ÙÙ‚Ø© Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø£Ùˆ Ø£Ù† Ù‡Ù†Ø§Ùƒ ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„ÙˆØ­Ø¯Ø§Øª.","3":"ØªÙ… ØªØ­Ø¯ÙŠØ¯ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ù„ØªØ´Ù…Ù„ Ø¬Ù…ÙŠØ¹ Ø§Ù„ÙˆØ­Ø¯Ø§Øª ÙˆØ§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆÙŠØªÙ… ØªÙ†ÙÙŠØ° Ø¬Ù…ÙŠØ¹ Ø§Ù„Ø·Ù„Ø¨Ø§Øª Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª.