INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (58, 'E.2.1', 'Ä°nsan KaynaklarÄ± YÃ¶netimi', 'Human Resources Management', 'Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ©', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda insan kaynaklarÄ± yÃ¶netimine iliÅŸkin tanÄ±mlÄ± bir politika ve sÃ¼reÃ§ler bulunmamaktadÄ±r.","2":"Kurumda insan kaynaklarÄ± yÃ¶netimi politikasÄ± ile bununla uyumlu olarak tanÄ±mlanmÄ±ÅŸ sÃ¼reÃ§leri bulunmaktadÄ±r. Ancak bunlarÄ± hayata geÃ§irmek Ã¼zere mekanizmalar veya uygulamalar bulunmamaktadÄ±r.","3":"Kurumun insan kaynaklarÄ± politikasÄ± ve stratejik hedefleri ile uyumlu olarak, insan kaynaklarÄ± sÃ¼reÃ§leri doÄŸrultusunda uygulamalar bulunmaktadÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda tÃ¼m birimleri kapsayan insan kaynaklarÄ± yÃ¶netimi uygulamalarÄ±na iliÅŸkin sonuÃ§lar sistematik olarak izlenmekte, paydaÅŸ gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda stratejik hedeflerle uyumlu ve tÃ¼m alanlarÄ± kapsayan insan kaynaklarÄ± yÃ¶netim modeli sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no defined policy and processes regarding human resources management in the institution.","2":"The institution has a human resources management policy and processes defined in accordance with it. However, there are no mechanisms or practices to implement these.","3":"In line with the human resources policy and strategic goals of the institution, there are practices in line with human resources processes and some results have been obtained from these practices. However, the results of these applications are not monitored or used in decision-making.","4":"The results of human resources management practices covering all units in the institution are systematically monitored, stakeholder opinions are received and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"The human resources management model, which is compatible with the strategic goals of the institution and covers all areas, has been adopted and secured throughout the institution with sustainable and mature practices; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø³ÙŠØ§Ø³Ø© ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© ÙÙŠÙ…Ø§ ÙŠØªØ¹Ù„Ù‚ Ø¨Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø³ÙŠØ§Ø³Ø© ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù„Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ© Ù…Ø­Ø¯Ø¯Ø© ÙˆÙÙ‚Ù‹Ø§ Ù„Ù‡Ø§. Ù„ÙƒÙ† Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¢Ù„ÙŠØ§Øª Ø£Ùˆ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„ØªÙ†ÙÙŠØ°Ù‡Ø§.","3":"ØªÙ…Ø§Ø´ÙŠØ§Ù‹ Ù…Ø¹ Ø³ÙŠØ§Ø³Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ© ÙˆØ§Ù„Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ© ÙˆÙ‚Ø¯ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù†ØªØ§Ø¦Ø¬ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ© Ø§Ù„ØªÙŠ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„ÙˆØ­Ø¯Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠØŒ ÙˆÙŠØªÙ… ØªÙ„Ù‚ÙŠ Ø¢Ø±Ø§Ø¡ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"Ø¥Ù† Ù†Ù…ÙˆØ°Ø¬ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ø¨Ø´Ø±ÙŠØ©ØŒ Ø§Ù„Ù…ØªÙˆØ§ÙÙ‚ Ù…Ø¹ Ø§Ù„Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆÙŠØºØ·ÙŠ ÙƒØ§ÙØ© Ø§Ù„Ù…Ø¬Ø§Ù„Ø§ØªØŒ ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯Ù‡ ÙˆØªØ£Ù…ÙŠÙ†Ù‡ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø©Ø› ÙˆÙ„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ø¹Ø¯ÙŠØ¯ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ÙØ±ÙŠØ¯Ø© ÙˆØ§Ù„Ù…Ø¨ØªÙƒØ±Ø© ÙÙŠ Ù‡Ø°Ø§ Ø§Ù„ØµØ¯Ø¯ØŒ ÙˆØ¨Ø¹Ø¶ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªØ®Ø°Ù‡Ø§ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰ Ù…Ø«Ø§Ù„Ø§Ù‹."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aciklama_metni":"","aciklama_metni_en":"","uygulama_alanlari":"","ilk_planlama_tarihi":"","izleme_mekanizmalari":"","uluslararasi_paydaslar":"","performans_gostergeleri":"","degerlendirme_iyilestirme_tarihi":""}'::jsonb) ON CONFLICT (id) DO UPDATE SET olcut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (59, 'E.2.2', 'Finansal KaynaklarÄ±n YÃ¶netimi', 'Management of Financial Resources', 'Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ©', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda finansal kaynaklarÄ±n yÃ¶netimine iliÅŸkin tanÄ±mlÄ± sÃ¼reÃ§ler bulunmamaktadÄ±r.","2":"Kurumda finansal kaynaklarÄ±n yÃ¶netimine iliÅŸkin tanÄ±mlÄ± sÃ¼reÃ§ler bulunmaktadÄ±r. Ancak bu sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya mevcut uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumun stratejik hedefleri ile uyumlu olarak, tanÄ±mlÄ± sÃ¼reÃ§lere gÃ¶re finansal kaynaklarÄ±n yÃ¶netimine iliÅŸkin uygulamalar bulunmaktadÄ±r ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda tÃ¼m alanlarÄ± kapsayacak ÅŸekilde yÃ¼rÃ¼tÃ¼len finansal kaynaklarÄ±n yÃ¶netimi uygulamalarÄ±na iliÅŸkin sonuÃ§lar sistematik olarak izlenmekte, paydaÅŸ gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda stratejik hedeflerle uyumlu ve tÃ¼m alanlarÄ± kapsayan finansal kaynaklarÄ±n yÃ¶netimi sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsemiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no defined processes for the management of financial resources in the institution.","2":"The institution has defined processes for the management of financial resources. However, there are no applications made in line with these processes or existing applications do not cover all areas.","3":"There are practices regarding the management of financial resources according to defined processes, in line with the strategic goals of the institution, and some results have been obtained from these practices. However, the results of these applications are not monitored or used in decision-making.","4":"The results of the financial resources management practices carried out in a way that covers all areas of the institution are systematically monitored, stakeholder opinions are received and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"The management of financial resources compatible with strategic goals and covering all areas in the institution has been adopted and secured throughout the institution with sustainable and mature practices; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‚Ø§Ù…Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨ØªØ­Ø¯ÙŠØ¯ Ø¹Ù…Ù„ÙŠØ§Øª Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ø·Ù„Ø¨Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø£Ùˆ Ø£Ù† Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø§Ù„Ø­Ø§Ù„ÙŠØ© Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"Ù‡Ù†Ø§Ùƒ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªØ¹Ù„Ù‚ Ø¨Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ© ÙˆÙÙ‚ Ø¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø©ØŒ Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø§Ù„Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© Ù„Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙ‚Ø¯ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù†ØªØ§Ø¦Ø¬ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ© Ø§Ù„ØªÙŠ ÙŠØªÙ… ØªÙ†ÙÙŠØ°Ù‡Ø§ Ø¨Ø·Ø±ÙŠÙ‚Ø© ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ù…Ø¬Ø§Ù„Ø§Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠØŒ ÙˆÙŠØªÙ… ØªÙ„Ù‚ÙŠ Ø¢Ø±Ø§Ø¡ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"ØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…ÙˆØ§Ø±Ø¯ Ø§Ù„Ù…Ø§Ù„ÙŠØ© Ø§Ù„Ù…ØªÙˆØ§ÙÙ‚Ø© Ù…Ø¹ Ø§Ù„Ø£Ù‡Ø¯Ø§Ù Ø§Ù„Ø¥Ø³ØªØ±Ø§ØªÙŠØ¬ÙŠØ© ÙˆØ§Ù„ØªÙŠ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙˆØªØ£Ù…ÙŠÙ†Ù‡Ø§ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø©Ø› ÙˆÙ„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ø¹Ø¯ÙŠØ¯ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ÙØ±ÙŠØ¯Ø© ÙˆØ§Ù„Ù…Ø¨ØªÙƒØ±Ø© ÙÙŠ Ù‡Ø°Ø§ Ø§Ù„ØµØ¯Ø¯ØŒ ÙˆØ¨Ø¹Ø¶ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªØ®Ø°Ù‡Ø§ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰ Ù…Ø«Ø§Ù„Ø§Ù‹."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aciklama_metni":"","aciklama_metni_en":"","uygulama_alanlari":"","ilk_planlama_tarihi":"","izleme_mekanizmalari":"","uluslararasi_paydaslar":"","performans_gostergeleri":"","degerlendirme_iyilestirme_tarihi":""}'::jsonb) ON CONFLICT (id) DO UPDATE SET olcut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (60, 'E.3.1', 'Entegre Bilgi YÃ¶netim Sistemi', 'Integrated Information Management System', 'Ù†Ø¸Ø§Ù… Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª Ø§Ù„Ù…ØªÙƒØ§Ù…Ù„', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda bilginin edinimi, saklanmasÄ± ve kullanÄ±lmasÄ±na destek olacak herhangi bir biliÅŸim sistemi bulunmamaktadÄ±r.","2":"Kurumda kurumsal bilginin edinimi, saklanmasÄ± ve kullanÄ±lmasÄ±na destek olacak bilgi yÃ¶netim sistemleri bulunmaktadÄ±r. Ancak bu sistem bÃ¼tÃ¼nleÅŸik deÄŸildir veya tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumda tÃ¼m alanlarÄ± kapsayan, tÃ¼m sÃ¼reÃ§leri destekleyen (eÄŸitim-Ã¶ÄŸretim, araÅŸtÄ±rma-geliÅŸtirme, toplumsal katkÄ±, kalite gÃ¼vencesi) entegre bilgi yÃ¶netim sistemi bulunmaktadÄ±r ve bu sistemin kullanÄ±lmasÄ± yÃ¶nÃ¼nde bazÄ± uygulamalar bulunmaktadÄ±r. Ancak bilgi sistemi karar almalarda kullanÄ±lmamaktadÄ±r ve sistemin kullanÄ±mÄ±yla ilgili sonuÃ§lar izlenmemektedir.","4":"Kurumda tÃ¼m sÃ¼reÃ§leri destekleyen entegre bilgi yÃ¶netim sistemine ve kullanÄ±mÄ±na iliÅŸkin sonuÃ§lar sistematik olarak izlenmekte, paydaÅŸ gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmakta ve ihtiyaÃ§lar/taleple doÄŸrultusunda gÃ¼ncellemeler gerÃ§ekleÅŸtirilmektedir.","5":"Kurumsal amaÃ§lar doÄŸrultusunda sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ entegre bilgi yÃ¶netim sistemi kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There is no information system in the institution to support the acquisition, storage and use of information.","2":"The institution has information management systems that will support the acquisition, storage and use of corporate information. However, this system is not integrated or does not cover all areas.","3":"The institution has an integrated information management system that covers all areas and supports all processes (education-training, research-development, social contribution, quality assurance), and there are some practices for using this system. However, the information system is not used in decision-making and the results of the use of the system are not monitored.","4":"The results regarding the integrated information management system and its use, which supports all processes in the institution, are systematically monitored, stakeholder opinions are received and the monitoring results are evaluated together with the stakeholders, measures are taken and updates are made in line with needs/demand.","5":"In line with corporate objectives, a sustainable and mature integrated information management system has been adopted and secured throughout the institution; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ÙŠÙˆØ¬Ø¯ Ù†Ø¸Ø§Ù… Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© ÙŠØ¯Ø¹Ù… Ø§ÙƒØªØ³Ø§Ø¨ Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙˆØªØ®Ø²ÙŠÙ†Ù‡Ø§ ÙˆØ§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§.","2":"ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø£Ù†Ø¸Ù…Ø© Ø¥Ø¯Ø§Ø±Ø© Ù…Ø¹Ù„ÙˆÙ…Ø§Øª Ù…Ù† Ø´Ø£Ù†Ù‡Ø§ Ø£Ù† ØªØ¯Ø¹Ù… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ù…Ø¹Ù„ÙˆÙ…Ø§Øª Ø§Ù„Ø´Ø±ÙƒØ© ÙˆØªØ®Ø²ÙŠÙ†Ù‡Ø§ ÙˆØ§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§. Ø¥Ù„Ø§ Ø£Ù† Ù‡Ø°Ø§ Ø§Ù„Ù†Ø¸Ø§Ù… Ù„ÙŠØ³ Ù…ØªÙƒØ§Ù…Ù„Ø§ Ø£Ùˆ Ù„Ø§ ÙŠØºØ·ÙŠ ÙƒØ§ÙØ© Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù†Ø¸Ø§Ù… Ù…ØªÙƒØ§Ù…Ù„ Ù„Ø¥Ø¯Ø§Ø±Ø© Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙŠØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª ÙˆÙŠØ¯Ø¹Ù… Ø¬Ù…ÙŠØ¹ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª (Ø§Ù„ØªØ¹Ù„ÙŠÙ… ÙˆØ§Ù„ØªØ¯Ø±ÙŠØ¨ ÙˆØ§Ù„Ø¨Ø­Ø« ÙˆØ§Ù„ØªØ·ÙˆÙŠØ± ÙˆØ§Ù„Ù…Ø³Ø§Ù‡Ù…Ø© Ø§Ù„Ø§Ø¬ØªÙ…Ø§Ø¹ÙŠØ© ÙˆØ¶Ù…Ø§Ù† Ø§Ù„Ø¬ÙˆØ¯Ø©)ØŒ ÙˆÙ‡Ù†Ø§Ùƒ Ø¨Ø¹Ø¶ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø§Ø³ØªØ®Ø¯Ø