INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (61, 'E.3.2', 'Bilgi GÃ¼venliÄŸi ve GÃ¼venilirliÄŸi', 'Information Security and Reliability', 'Ø£Ù…Ù† Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙˆØ§Ù„Ù…ÙˆØ«ÙˆÙ‚ÙŠØ©', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda bilgi gÃ¼venliÄŸi ve gÃ¼venirliÄŸinin saÄŸlanmasÄ±na iliÅŸkin uygulamalar bulunmamaktadÄ±r.","2":"Kurumda bilgi gÃ¼venliÄŸi ve gÃ¼venirliÄŸinin saÄŸlanmasÄ±na yÃ¶nelik tanÄ±mlÄ± sÃ¼reÃ§ler ve planlamalar bulunmaktadÄ±r. Ancak bu sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya uygulamalar tÃ¼m birimleri kapsamamaktadÄ±r.","3":"Kurumda bilgi gÃ¼venliÄŸi ve gÃ¼venirliÄŸinin saÄŸlanmasÄ±na yÃ¶nelik bÃ¼tÃ¼nleÅŸik uygulamalar bulunmakta ve bu uygulamalardan bazÄ± sonuÃ§lar elde edilmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda bilgi gÃ¼venliÄŸi ve gÃ¼venirliÄŸinin saÄŸlanmasÄ±na yÃ¶nelik uygulamalar sistematik olarak izlenmekte ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumsal bilginin gÃ¼venliÄŸi ve gÃ¼venirliÄŸi sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla kurumun tamamÄ±nda benimsenmiÅŸ ve gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸtÄ±r; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"There are no practices to ensure information security and reliability in the institution.","2":"The institution has defined processes and plans to ensure information security and reliability. However, there are no practices made in line with these processes or the practices do not cover all units.","3":"There are integrated applications to ensure information security and reliability in the institution, and some results are obtained from these applications. However, the results of these applications are not monitored or used in decision-making.","4":"Practices to ensure information security and reliability in the institution are systematically monitored, and the monitoring results are evaluated together with stakeholders and precautions are taken.","5":"The security and reliability of corporate information is adopted and guaranteed throughout the institution with sustainable and mature practices; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø¶Ù…Ø§Ù† Ø£Ù…Ù† ÙˆÙ…ÙˆØ«ÙˆÙ‚ÙŠØ© Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©.","2":"Ù‚Ø§Ù…Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨ØªØ­Ø¯ÙŠØ¯ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª ÙˆØ§Ù„Ø®Ø·Ø· Ù„Ø¶Ù…Ø§Ù† Ø£Ù…Ù† Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙˆÙ…ÙˆØ«ÙˆÙ‚ÙŠØªÙ‡Ø§. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø£Ùˆ Ø£Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„ÙˆØ­Ø¯Ø§Øª.","3":"ØªÙˆØ¬Ø¯ ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ù…ØªÙƒØ§Ù…Ù„Ø© Ù„Ø¶Ù…Ø§Ù† Ø£Ù…Ù† ÙˆÙ…ÙˆØ«ÙˆÙ‚ÙŠØ© Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙŠØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø¶Ù…Ø§Ù† Ø£Ù…Ù† Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª ÙˆÙ…ÙˆØ«ÙˆÙ‚ÙŠØªÙ‡Ø§ ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø´ÙƒÙ„ Ù…Ù†Ù‡Ø¬ÙŠØŒ ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"ÙŠØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯ ÙˆØ¶Ù…Ø§Ù† Ø£Ù…Ù† ÙˆÙ…ÙˆØ«ÙˆÙ‚ÙŠØ© Ù…Ø¹Ù„ÙˆÙ…Ø§Øª Ø§Ù„Ø´Ø±ÙƒØ© ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ù† Ø®Ù„Ø§Ù„ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø©Ø› ÙˆÙ„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø§Ù„Ø¹Ø¯ÙŠØ¯ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ÙØ±ÙŠØ¯Ø© ÙˆØ§Ù„Ù…Ø¨ØªÙƒØ±Ø© ÙÙŠ Ù‡Ø°Ø§ Ø§Ù„ØµØ¯Ø¯ØŒ ÙˆØ¨Ø¹Ø¶ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªØ®Ø°Ù‡Ø§ Ù…Ø¤Ø³Ø³Ø§Øª Ø£Ø®Ø±Ù‰ Ù…Ø«Ø§Ù„Ø§Ù‹."}'::jsonb, NULL, NULL, '{"bgs_yeri":"","ic_paydaslar":"","dis_paydaslar":"","sorumlu_birim":"","aciklama_metni":"","aciklama_metni_en":"","uygulama_alanlari":"","ilk_planlama_tarihi":"","izleme_mekanizmalari":"","uluslararasi_paydaslar":"","performans_gostergeleri":"","degerlendirme_iyilestirme_tarihi":""}'::jsonb) ON CONFLICT (id) DO UPDATE SET olcut_adi = EXCLUDED.olcut_adi, kalite_el_kitabi = EXCLUDED.kalite_el_kitabi;
INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (62, 'E.4.1', 'Hizmet ve MallarÄ±n UygunluÄŸu, Kalitesi ve SÃ¼rekliliÄŸi', 'Suitability, Quality and Continuity of Services and Goods', 'Ø§Ù„Ù…Ù„Ø§Ø¡Ù…Ø© ÙˆØ§Ù„Ø¬ÙˆØ¯Ø© ÙˆØ§Ø³ØªÙ…Ø±Ø§Ø±ÙŠØ© Ø§Ù„Ø®Ø¯Ù…Ø§Øª ÙˆØ§Ù„Ø³Ù„Ø¹', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumda, dÄ±ÅŸarÄ±dan temin edilen mallarÄ±n ve destek hizmetlerinin uygunluÄŸunu ve kalitesini deÄŸerlendirmek Ã¼zere tanÄ±mlÄ± kriterler ve sÃ¼reÃ§ler bulunmamaktadÄ±r.","2":"Kurumda, dÄ±ÅŸarÄ±dan temin edilen destek hizmetlerinin ve mallarÄ±n uygunluÄŸunu, kalitesini ve sÃ¼rekliliÄŸini gÃ¼vence altÄ±na almak Ã¼zere bazÄ± tanÄ±mlÄ± sÃ¼reÃ§ler ve mekanizmalar (tedarik sÃ¼reci, uygunluk ve kalite kriterleri gibi) bulunmaktadÄ±r. Ancak bu sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lan uygulamalar bulunmamaktadÄ±r veya uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumda, dÄ±ÅŸarÄ±dan temin edilen tÃ¼m mallardan ve destek hizmetlerinden beklenen kalite dÃ¼zeylerinin iÃ§ kalite gÃ¼vence sistemi kapsamÄ±nda planlanmasÄ±, deÄŸerlendirilip iyileÅŸtirilmesi yÃ¶nÃ¼nde uygulamalar gerÃ§ekleÅŸtirilmektedir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumda, dÄ±ÅŸarÄ±dan tedarik edilen tÃ¼m hizmetlerin ve mallarÄ±n kalitesini gÃ¼vence altÄ±na almak Ã¼zere tedarikÃ§ilerle yakÄ±n iÅŸbirlikleri yÃ¼rÃ¼tÃ¼lmekte, tedarikÃ§ilerin performansÄ± ve memnuniyetleri sistematik olarak izlenerek paydaÅŸlarla birlikte deÄŸerlendirilmekte ve gerekli Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumda dÄ±ÅŸarÄ±dan temin edilen mal ve hizmetlerin kalite dÃ¼zeylerini, kurumsal amaÃ§lar doÄŸrultusunda gÃ¼vence altÄ±na almak Ã¼zere tedarik zinciri yÃ¶netilmektedir; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have defined criteria and processes to evaluate the suitability and quality of externally procured goods and support services.","2":"The institution has some defined processes and mechanisms (such as procurement process, compliance and quality criteria) to ensure the suitability, quality and continuity of outsourced support services and goods. However, there are no applications made in line with these processes or the applications do not cover all areas.","3":"In the institution, practices are carried out to plan, evaluate and improve the quality levels expected from all externally procured goods and support services within the scope of the internal quality assurance system. However, the results of these applications are not monitored or used in decision-making.","4":"The institution maintains close collaborations with suppliers to ensure the quality of all externally procured services and goods, the performance and satisfaction of suppliers are systematically monitored and evaluated together with stakeholders, and necessary precautions are taken.","5":"The supply chain is managed in the institution to ensure the quality levels of externally procured goods and services in line with corporate objectives; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„ÙŠØ³ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ø¹Ø§ÙŠÙŠØ± ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„ØªÙ‚ÙŠÙŠÙ… Ù…Ø¯Ù‰ Ù…Ù„Ø§Ø¡Ù…Ø© ÙˆØ¬ÙˆØ¯Ø© Ø§Ù„Ø³Ù„Ø¹ Ø§Ù„Ù…Ø´ØªØ±Ø§Ø© Ù…Ù† Ø§Ù„Ø®Ø§Ø±Ø¬ ÙˆØ®Ø¯Ù…Ø§Øª Ø§Ù„Ø¯Ø¹Ù….","2":"Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ø¹Ø¶ Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª ÙˆØ§Ù„Ø¢Ù„ÙŠØ§Øª Ø§Ù„Ù…Ø­Ø¯Ø¯Ø© (Ù…Ø«Ù„ Ø¹Ù…Ù„ÙŠØ© Ø§Ù„Ø´Ø±Ø§Ø¡ ÙˆØ§Ù„Ø§Ù…ØªØ«Ø§Ù„ ÙˆÙ…Ø¹Ø§ÙŠÙŠØ± Ø§Ù„Ø¬ÙˆØ¯Ø©) Ù„Ø¶Ù…Ø§Ù† Ù…Ù„Ø§Ø¡Ù…Ø© ÙˆØ¬ÙˆØ¯Ø© ÙˆØ§Ø³ØªÙ…Ø±Ø§Ø±ÙŠØ© Ø®Ø¯Ù…Ø§Øª ÙˆØ³Ù„Ø¹ Ø§Ù„Ø¯Ø¹Ù… Ø§Ù„Ø®Ø§Ø±Ø¬ÙŠØ©. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù