INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (63, 'E.5.1', 'Kamuoyunu Bilgilendirme', 'Public Information', 'Ø§Ù„Ù…Ø¹Ù„ÙˆÙ…Ø§Øª Ø§Ù„Ø¹Ø§Ù…Ø©', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun faaliyetlerine iliÅŸkin kamuoyunu bilgilendirmek Ã¼zere tanÄ±mlÄ± ilkeleri ve mekanizmalarÄ± bulunmamaktadÄ±r.","2":"Kurum, faaliyetlerine iliÅŸkin kamuoyunu bilgilendirmeyi ilkesel olarak benimsemek Ã¼zere bir politika tanÄ±mlamÄ±ÅŸ, kamuoyunu bilgilendirme yÃ¶ntem ve sÃ¼reÃ§lerini belirlemiÅŸtir. Ancak bu politika ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumun kamuoyunu bilgilendirmek Ã¼zere belirlediÄŸi ilkeler ve sÃ¼reÃ§ler doÄŸrultusunda, tÃ¼m alanlarÄ± kapsayan kamuoyunu bilgilendirme uygulamalarÄ±ndan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumun kamuoyunu bilgilendirme faaliyetlerine iliÅŸkin bulgular izlenmekte, paydaÅŸ gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumun kamuoyunu bilgilendirme faaliyetleri kurumsal amaÃ§lar ve deÄŸerler doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸ ve kurumun tamamÄ±nda benimsenmiÅŸtir; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have defined principles and mechanisms to inform the public about its activities.","2":"The institution has defined a policy to adopt the principle of informing the public about its activities and has determined the methods and processes of informing the public. However, there are no practices made in line with these policies and processes, or the practices do not cover all areas.","3":"In line with the principles and processes determined by the institution to inform the public, some results have been obtained from public information practices covering all areas. However, the results of these applications are not monitored or used in decision-making.","4":"Findings regarding the institution''s public information activities are monitored, stakeholder opinions are received, and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"The institution''s public information activities are secured by sustainable and mature practices, in line with corporate goals and values, and adopted throughout the institution; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„ÙŠØ³ Ù„Ø¯Ù‰ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ø¨Ø§Ø¯Ø¦ ÙˆØ¢Ù„ÙŠØ§Øª Ù…Ø­Ø¯Ø¯Ø© Ù„Ø¥Ø¹Ù„Ø§Ù… Ø§Ù„Ø¬Ù…Ù‡ÙˆØ± Ø¨Ø£Ù†Ø´Ø·ØªÙ‡Ø§.","2":"ÙˆÙ‚Ø¯ Ø­Ø¯Ø¯Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø³ÙŠØ§Ø³Ø© Ù„ØªØ¨Ù†ÙŠ Ù…Ø¨Ø¯Ø£ Ø¥Ø¹Ù„Ø§Ù… Ø§Ù„Ø¬Ù…Ù‡ÙˆØ± Ø¹Ù† Ø£Ù†Ø´Ø·ØªÙ‡Ø§ ÙˆØ­Ø¯Ø¯Øª Ø£Ø³Ø§Ù„ÙŠØ¨ ÙˆØ¹Ù…Ù„ÙŠØ§Øª Ø¥Ø¹Ù„Ø§Ù… Ø§Ù„Ø¬Ù…Ù‡ÙˆØ±. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ù…Ù…Ø§Ø±Ø³Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ø³ÙŠØ§Ø³Ø§Øª ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§ØªØŒ Ø£Ùˆ Ø£Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ÙˆØªÙ…Ø´ÙŠØ§ Ù…Ø¹ Ø§Ù„Ù…Ø¨Ø§Ø¯Ø¦ ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªÙŠ ØªØ­Ø¯Ø¯Ù‡Ø§ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù„Ø¥Ø¹Ù„Ø§Ù… Ø§Ù„Ø¬Ù…Ù‡ÙˆØ±ØŒ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„Ø¥Ø¹Ù„Ø§Ù… Ø§Ù„Ø¹Ø§Ù… Ø§Ù„ØªÙŠ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…ØªØ¹Ù„Ù‚Ø© Ø¨Ø§Ù„Ø£Ù†Ø´Ø·Ø© Ø§Ù„Ø¥Ø¹Ù„Ø§Ù…ÙŠØ© Ø§Ù„Ø¹Ø§Ù…Ø© Ù„Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙŠØªÙ