INSERT INTO public.alt_olcutler (id, kod, olcut_adi, olcut_adi_en, olcut_adi_ar, ana_baslik_id, aciklama, olusturulma_tarihi, olgunluk_duzeyleri, rubrik_aciklamalari, olgunluk_duzeyleri_en, olgunluk_duzeyleri_ar, erisim_baslangic, erisim_bitis, kalite_el_kitabi) VALUES (64, 'E.5.2', 'Hesap Verme YÃ¶ntemleri', 'Methods of Accountability', 'Ø£Ø³Ø§Ù„ÙŠØ¨ Ø§Ù„Ù…Ø³Ø§Ø¡Ù„Ø©', 5, NULL, '2026-05-13T02:30:32.353681', '{"1":"Kurumun hesap verme yÃ¶ntemleri ve mekanizmalarÄ± bulunmamaktadÄ±r.","2":"Kurum hesap vermeyi ilkesel olarak benimsemiÅŸ, yÃ¶ntem ve sÃ¼reÃ§lerini belirlemiÅŸtir. Ancak bu ilkeler ve sÃ¼reÃ§ler doÄŸrultusunda yapÄ±lmÄ±ÅŸ uygulamalar bulunmamaktadÄ±r veya uygulamalar tÃ¼m alanlarÄ± kapsamamaktadÄ±r.","3":"Kurumun hesap vermek Ã¼zere benimsemiÅŸ olduÄŸu ilkeler ve sÃ¼reÃ§ler doÄŸrultusunda yaptÄ±ÄŸÄ± uygulamalardan bazÄ± sonuÃ§lar elde edilmiÅŸtir. Ancak bu uygulamalarÄ±n sonuÃ§larÄ± izlenmemekte veya karar almalarda kullanÄ±lmamaktadÄ±r.","4":"Kurumun hesap verme faaliyetleri sonucunda elde edilen bulgular izlenmekte, paydaÅŸ gÃ¶rÃ¼ÅŸleri alÄ±nmakta ve izlem sonuÃ§larÄ± paydaÅŸlarla birlikte deÄŸerlendirilerek Ã¶nlemler alÄ±nmaktadÄ±r.","5":"Kurumun hesap verme ilkeleri, kurumsal amaÃ§lar ve deÄŸerler doÄŸrultusunda, sÃ¼rdÃ¼rÃ¼lebilir ve olgunlaÅŸmÄ±ÅŸ uygulamalarla gÃ¼vence altÄ±na alÄ±nmÄ±ÅŸ ve kurumun tamamÄ±nda benimsenmiÅŸtir; bu hususta kurumun kendine Ã¶zgÃ¼ ve yenilikÃ§i birÃ§ok uygulamasÄ± bulunmakta ve bu uygulamalarÄ±n bir kÄ±smÄ± diÄŸer kurumlar tarafÄ±ndan Ã¶rnek alÄ±nmaktadÄ±r."}'::jsonb, NULL, '{"1":"The institution does not have accountability methods and mechanisms.","2":"The institution has adopted accountability as a principle and determined its methods and processes. However, there are no applications made in line with these principles and processes, or the applications do not cover all areas.","3":"Some results have been obtained from the practices carried out by the institution in line with the principles and processes it has adopted to account for it. However, the results of these applications are not monitored or used in decision-making.","4":"The findings obtained as a result of the institution''s accountability activities are monitored, stakeholder opinions are received, and the monitoring results are evaluated together with the stakeholders and precautions are taken.","5":"The accountability principles of the institution are secured by sustainable and mature practices, in line with corporate goals and values, and are adopted throughout the institution; The institution has many unique and innovative practices in this regard, and some of these practices are taken as an example by other institutions."}'::jsonb, '{"1":"Ù„Ø§ ØªÙ…ØªÙ„Ùƒ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø£Ø³Ø§Ù„ÙŠØ¨ ÙˆØ¢Ù„ÙŠØ§Øª Ù„Ù„Ù…Ø³Ø§Ø¡Ù„Ø©.","2":"Ù„Ù‚Ø¯ ØªØ¨Ù†Øª Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ø¨Ø¯Ø£ Ø§Ù„Ù…Ø³Ø§Ø¡Ù„Ø© ÙˆØ­Ø¯Ø¯Øª Ø£Ø³Ø§Ù„ÙŠØ¨Ù‡Ø§ ÙˆØ¹Ù…Ù„ÙŠØ§ØªÙ‡Ø§. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ØªÙˆØ¬Ø¯ Ø·Ù„Ø¨Ø§Øª ØªØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ù‡Ø°Ù‡ Ø§Ù„Ù…Ø¨Ø§Ø¯Ø¦ ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§ØªØŒ Ø£Ùˆ Ø£Ù† Ø§Ù„Ø·Ù„Ø¨Ø§Øª Ù„Ø§ ØªØºØ·ÙŠ Ø¬Ù…ÙŠØ¹ Ø§Ù„Ù…Ø¬Ø§Ù„Ø§Øª.","3":"ÙˆÙ‚Ø¯ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø¨Ø¹Ø¶ Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ù…Ù† Ø§Ù„Ù…Ù…Ø§Ø±Ø³Ø§Øª Ø§Ù„ØªÙŠ Ù‚Ø§Ù…Øª Ø¨Ù‡Ø§ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ø¨Ù…Ø§ ÙŠØªÙˆØ§ÙÙ‚ Ù…Ø¹ Ø§Ù„Ù…Ø¨Ø§Ø¯Ø¦ ÙˆØ§Ù„Ø¹Ù…Ù„ÙŠØ§Øª Ø§Ù„ØªÙŠ Ø§Ø¹ØªÙ…Ø¯ØªÙ‡Ø§ Ù„Ù…Ø­Ø§Ø³Ø¨ØªÙ‡Ø§. ÙˆÙ…Ø¹ Ø°Ù„ÙƒØŒ Ù„Ø§ ÙŠØªÙ… Ø±ØµØ¯ Ù†ØªØ§Ø¦Ø¬ Ù‡Ø°Ù‡ Ø§Ù„ØªØ·Ø¨ÙŠÙ‚Ø§Øª Ø£Ùˆ Ø§Ø³ØªØ®Ø¯Ø§Ù…Ù‡Ø§ ÙÙŠ Ø§ØªØ®Ø§Ø° Ø§Ù„Ù‚Ø±Ø§Ø±.","4":"ØªØªÙ… Ù…Ø±Ø§Ù‚Ø¨Ø© Ø§Ù„Ù†ØªØ§Ø¦Ø¬ Ø§Ù„ØªÙŠ ØªÙ… Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„ÙŠÙ‡Ø§ Ù†ØªÙŠØ¬Ø© Ù„Ø£Ù†Ø´Ø·Ø© Ø§Ù„Ù…Ø³Ø§Ø¡Ù„Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©ØŒ ÙˆÙŠØªÙ… ØªÙ„Ù‚ÙŠ Ø¢Ø±Ø§Ø¡ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø©ØŒ ÙˆÙŠØªÙ… ØªÙ‚ÙŠÙŠÙ… Ù†ØªØ§Ø¦Ø¬ Ø§Ù„Ù…Ø±Ø§Ù‚Ø¨Ø© Ù…Ø¹ Ø£ØµØ­Ø§Ø¨ Ø§Ù„Ù…ØµÙ„Ø­Ø© ÙˆÙŠØªÙ… Ø§ØªØ®Ø§Ø° Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·Ø§Øª Ø§Ù„Ù„Ø§Ø²Ù…Ø©.","5":"ÙŠØªÙ… ØªØ£Ù…ÙŠÙ† Ù…Ø¨Ø§Ø¯Ø¦ Ø§Ù„Ù…Ø³Ø§Ø¡Ù„Ø© ÙÙŠ Ø§Ù„Ù…Ø¤Ø³Ø³Ø© Ù…Ù† Ø®Ù„Ø§Ù„ Ù…Ù…Ø§Ø±Ø³Ø§Øª Ù…Ø³ØªØ¯Ø§Ù…Ø© ÙˆÙ†Ø§Ø¶Ø¬Ø©ØŒ Ø¨Ù…Ø§ ÙŠØªÙ…Ø§Ø´Ù‰ Ù…Ø¹ Ø£Ù‡Ø¯Ø§Ù ÙˆÙ‚ÙŠÙ… Ø§Ù„Ø´Ø±ÙƒØ©ØŒ ÙˆÙŠØªÙ… Ø§Ø¹ØªÙ…Ø§Ø¯Ù‡Ø§ ÙÙŠ Ø¬Ù…ÙŠØ¹ Ø£Ù†Ø­Ø§Ø¡ Ø§Ù„Ù…Ø¤Ø³Ø³Ø©Ø›